(function () {
/* A64 frozen manifest; 20-lemma checkpoints are validated before publication. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});
D('loath',{etymology:E('Loath comes from Old English lāth, “hateful or hostile,” and developed the adjective sense “unwilling”; it commonly appears in “be loath to do.”','loath'),contexts:[C('loath.s1','工作安排','I am loath to cancel the field visit, but the storm warning makes the road unsafe.','我不愿取消实地考察，但暴风警报使道路变得不安全。','I am loath to cancel the field visit / but the storm warning / makes the road unsafe.','loath.s1 表示不情愿做某事，常与 to 加动词原形连用。','说话人不愿取消活动，但安全因素迫使其考虑取消。')],mistakes:[M('She was loath to leave because she eagerly wanted to go and had no hesitation at all.','She was loath to leave because she wanted to stay.','loath 表示不愿意；急切想离开与此义相反。')],quiz:[Q('loath',1,1,'If Nina is loath to complain, she is?','unwilling to complain','eager to complain','unable to understand','unwilling to complain','loath 表示不情愿。'),Q('loath',2,1,'Which phrase uses loath naturally?','He was loath to admit the mistake.','He loath to the room yesterday.','The loath measured three meters.','He was loath to admit the mistake.','常见结构是 be loath to do。','collocation'),Q('loath',3,2,'A loath response may show?','hesitation or reluctance','enthusiastic agreement','physical size','hesitation or reluctance','loath 也可表示显出勉强或迟疑。'),Q('loath',4,1,'The closest opposite of “loath to help” is?','willing to help','unable to help','late to help','willing to help','willing 表示愿意，与 loath 的不情愿相反。','confusable')]});
D('loathe',{etymology:E('Loathe is related to Old English lāth, “hateful”; as a verb it means to feel intense dislike or disgust toward someone or something.','loathe'),contexts:[C('loathe.s1','个人偏好','Although she loathes the smell of burnt coffee, she stays in the kitchen to help her brother clean up.','尽管她极其厌恶焦咖啡的气味，仍留在厨房帮弟弟收拾。','Although she loathes the smell of burnt coffee / she stays in the kitchen / to help her brother / clean up.','loathe 是及物动词，表示强烈厌恶某人或某物。','她对气味有强烈反感，但仍愿意帮忙。')],mistakes:[M('He loathes the bitter medicine and looks forward to drinking it every morning.','He loathes the bitter medicine and tries to avoid its taste.','期待饮用说明喜欢，而 loathe 表示强烈厌恶。')],quiz:[Q('loathe',1,1,'To loathe a food is to?','dislike it intensely','borrow it temporarily','prepare it carefully','dislike it intensely','loathe 表示强烈厌恶。'),Q('loathe',2,1,'Which sentence uses loathe correctly?','They loathe the noise from the late-night construction.','They loathe to the station by bus.','The loathe was painted blue.','They loathe the noise from the late-night construction.','loathe 后可直接接厌恶的对象。','grammar'),Q('loathe',3,1,'Loathe is stronger than?','dislike','measure','locate','dislike','loathe 表示程度很强的反感。'),Q('loathe',4,1,'If Omar loathes cruelty, he?','feels strong disgust toward it','supports it enthusiastically','is unable to notice it','feels strong disgust toward it','强烈反感 cruelty 符合 loathe 的词义。')]});
D('loathing',{etymology:E('Loathing is formed from loathe with the noun-forming -ing; it names a strong feeling of hatred or disgust.','loathing'),contexts:[C('loathing.s1','公共讨论','Her loathing of corruption was clear when she described how it deprived families of basic services.','她谈到腐败如何剥夺家庭的基本服务时，明显流露出强烈的憎恶。','Her loathing of corruption / was clear / when she described / how it deprived families of basic services.','loathing 是名词，表示强烈的厌恶或憎恶，常与 of 连用。','她对腐败的批评体现了强烈反感。')],mistakes:[M('His loathing of the unfair rule was obvious because he praised it and asked that it be extended.','His loathing of the unfair rule was obvious because he condemned it as harmful.','赞扬并要求延续某规则与憎恶该规则相矛盾。')],quiz:[Q('loathing',1,1,'Loathing is a feeling of?','strong hatred or disgust','mild curiosity','physical exhaustion','strong hatred or disgust','loathing 指强烈憎恶。'),Q('loathing',2,1,'Which phrase is idiomatic?','loathing of injustice','loathing at a sandwich to','loathing by three meters','loathing of injustice','loathing 常与 of 连用。','collocation'),Q('loathing',3,1,'A person’s loathing of cruelty would lead them to?','condemn cruel acts','celebrate cruelty','ignore every victim','condemn cruel acts','憎恶残酷行为的人通常会谴责这种行为。'),Q('loathing',4,1,'Loathing is the noun related to?','loathe','lobby','lobe','loathe','loathing 是 loathe 的名词形式。','word-formation')]});
D('loathsome',{etymology:E('Loathsome combines loath with -some, forming an adjective for something extremely unpleasant or deserving disgust.','loathsome'),contexts:[C('loathsome.s1','环境卫生','The inspector found a loathsome layer of spoiled food beneath the broken refrigerator.','检查员在损坏的冰箱下面发现了一层令人作呕的腐坏食物。','The inspector found / a loathsome layer of spoiled food / beneath / the broken refrigerator.','loathsome 形容令人极其厌恶、作呕的事物。','食物腐坏并散发恶臭，令检查员感到恶心。')],mistakes:[M('The kitchen was called loathsome even though it was spotless, fresh-smelling, and pleasant to eat in.','The kitchen was called loathsome because spoiled food and a foul odor filled it.','洁净宜人的环境与令人作呕的 loathsome 含义相反。')],quiz:[Q('loathsome',1,1,'A loathsome smell is?','extremely unpleasant','faint but pleasant','impossible to detect','extremely unpleasant','loathsome 指令人厌恶的。'),Q('loathsome',2,1,'Which scene could be called loathsome?','rotting food covered with insects','fresh bread cooling on a clean table','a flower garden after rain','rotting food covered with insects','腐坏食物和虫子可能令人作呕。'),Q('loathsome',3,1,'Loathsome is closest in meaning to?','disgusting','local','careful','disgusting','disgusting 与 loathsome 意义接近。','meaning'),Q('loathsome',4,1,'The suffix -some in loathsome helps form a(n)?','adjective','plural noun','past-tense verb','adjective','loathsome 是形容词。','word-formation')]});
D('lobby',{etymology:E('Lobby came from Medieval Latin lobia, “covered walk,” through French; it names an entrance hall, a pressure group, and the act of trying to influence decision-makers.','lobby'),contexts:[C('lobby.s1','公共建筑','Visitors waited in the museum lobby while staff checked the fire alarm.','工作人员检查火警时，访客在博物馆门厅等候。','Visitors waited / in the museum lobby / while staff checked / the fire alarm.','lobby.s1 指酒店、博物馆等建筑入口内的大堂或门厅。','访客在入口附近的等候空间内停留。'),C('lobby.s3','政策倡议','Residents plan to lobby the council for safer crossings near the school.','居民计划游说市议会，在学校附近设置更安全的人行横道。','Residents plan to lobby the council / for safer crossings / near the school.','lobby.s3 作动词，表示游说有权决策的人支持某项主张。','居民向市议会提出具体政策诉求。')],mistakes:[M('The residents lobbied the council by avoiding contact and refusing to explain their request.','The residents lobbied the council by meeting members and arguing for safer crossings.','游说需要试图影响决策者，而不是拒绝接触。')],quiz:[Q('lobby',1,1,'A hotel lobby is usually?','a hall near its entrance','a private bedroom on the top floor','a kitchen appliance','a hall near its entrance','lobby.s1 是入口附近的大堂。'),Q('lobby',2,2,'A political lobby is a group that tries to?','influence decision-makers','repair hotel rooms','keep people from voting','influence decision-makers','lobby.s2 指试图影响政策的团体。'),Q('lobby',3,3,'To lobby officials is to?','try to persuade them to support a cause','wait silently in a hallway','lock their office doors','try to persuade them to support a cause','lobby.s3 作动词表示游说。'),Q('lobby',4,1,'Which use of lobby is a building space?','We met in the courthouse lobby.','We lobbied for a new library.','A lobby asked the mayor for a meeting.','We met in the courthouse lobby.','只有该句用 lobby 指入口门厅。')]});
D('lobe',{etymology:E('Lobe came through Latin lobus from Greek lobos, a rounded projection; it refers to the soft lower part of an ear or a rounded division of an organ.','lobe'),contexts:[C('lobe.s1','医学检查','The scan showed a small shadow in the upper lobe of the patient’s left lung.','扫描显示患者左肺上叶有一小片阴影。','The scan showed a small shadow / in the upper lobe / of the patient’s left lung.','lobe.s1 指耳朵的圆形部分，也指器官的分叶。','肺部上叶是器官的一个分区。')],mistakes:[M('The radiologist described the entire lung as one lobe and said that no smaller divisions existed.','The radiologist identified the shadow in one lobe of the lung.','lobe 可指器官中较大的分叶，并非否认分区的整体名称。')],quiz:[Q('lobe',1,1,'The earlobe is?','the soft rounded lower part of the ear','the hard center of a tooth','a section of a hallway','the soft rounded lower part of the ear','lobe.s1 可指耳垂。'),Q('lobe',2,1,'A lung lobe is?','one rounded division of the lung','a bone in the wrist','a door lock','one rounded division of the lung','器官 lobe 指分叶。'),Q('lobe',3,1,'Which phrase uses lobe anatomically?','the frontal lobe of the brain','the lobby of the brain','the loathe of the brain','the frontal lobe of the brain','大脑额叶是 brain lobe。'),Q('lobe',4,1,'A lobe is generally a rounded?','part or division of an organ','kind of tax','written accusation','part or division of an organ','器官 lobe 是其圆形部分或分区。')]});
D('lobster',{etymology:E('Lobster developed from Old English loppestre, related to Latin locusta, “locust”; today it chiefly names a large clawed marine crustacean and its edible flesh.','lobster'),contexts:[C('lobster.s1','海洋生物','The tagged lobster was released beyond the harbor after researchers recorded its shell and claw size.','研究人员记录了这只龙虾的甲壳和钳子大小后，将带标签的它放回港外海域。','The tagged lobster was released / beyond the harbor / after researchers recorded / its shell and claw size.','lobster.s1 指有坚硬外壳和大螯的海生甲壳动物。','研究人员记录外壳、螯肢并将动物放归海中。')],mistakes:[M('The biologist called the lobster a freshwater fish with scales and no claws.','The biologist identified the lobster as a marine crustacean with a hard shell and claws.','龙虾是甲壳动物，不是有鳞的淡水鱼。')],quiz:[Q('lobster',1,1,'A lobster is a?','marine crustacean with a hard shell and claws','small songbird','freshwater plant','marine crustacean with a hard shell and claws','lobster.s1 是有螯的海生甲壳动物。'),Q('lobster',2,2,'Lobster can also mean?','the animal’s meat served as food','a room near an entrance','a narrow Scottish lake','the animal’s meat served as food','lobster.s2 也指供食用的龙虾肉。'),Q('lobster',3,1,'Which habitat is most typical for a lobster?','salt water near a rocky coast','a dry desert','the upper branches of a tree','salt water near a rocky coast','龙虾通常生活在海水环境。'),Q('lobster',4,1,'A lobster’s large pincers are its?','claws','lobes','flanges','claws','lobster 通常有一对大螯。')]});
D('local',{etymology:E('Local comes from Latin localis, “of a place,” from locus “place”; it can describe a particular area, a resident, or a nearby pub in British usage.','local'),contexts:[C('local.s1','公共服务','The clinic hired a local interpreter who knew the dialect spoken in the valley.','诊所聘请了一位当地口译员，他熟悉山谷里使用的方言。','The clinic hired a local interpreter / who knew the dialect / spoken in the valley.','local.s1 作形容词，表示属于或影响某一特定地方的。','口译员熟悉该地区方言，因此是当地的。'),C('local.s2','社区活动','A local told us which footpath remains open after the river floods.','一位当地居民告诉我们河水泛滥后哪条小路仍然开放。','A local told us / which footpath remains open / after the river floods.','local.s2 作名词，指所谈地区的居民。','此人住在当地，对社区情况熟悉。')],mistakes:[M('The guide called a visitor from another country a local even though the visitor had never lived in or near the town.','The guide called a long-time town resident a local.','local 名词指当地居民，并非所有到访者。')],quiz:[Q('local',1,1,'A local school serves?','a particular nearby area','the whole planet equally','only people who lived centuries ago','a particular nearby area','local.s1 指与某地相关。'),Q('local',2,2,'A local is?','a person who lives in the area','a visitor passing through once','a person who owns every pub','a person who lives in the area','local.s2 指当地居民。'),Q('local',3,3,'In British English, “the local” may mean?','a nearby pub','the town’s courthouse','a nearby lake','a nearby pub','local.s3 可口语指附近常去的酒吧。'),Q('local',4,1,'Which person is a local?','someone who has lived in the neighborhood for years','a tourist who arrived an hour ago','a caller who has never visited','someone who has lived in the neighborhood for years','长期住在社区的人是当地居民。')]});
D('locale',{etymology:E('Locale is borrowed from French local, “local,” ultimately from Latin locus “place”; it means the setting or place where something happens.','locale'),contexts:[C('locale.s1','影视制作','The director chose a quiet coastal village as the locale for the final scenes.','导演选了一座安静的海滨村庄作为最后几场戏的拍摄地点。','The director chose / a quiet coastal village / as the locale / for the final scenes.','locale 指某事件或故事发生的场所、背景地点。','村庄被选作剧情场景的发生地。')],mistakes:[M('The village was the locale of the film even though none of the story or filming took place there.','The village was the locale because the final scenes were set and filmed there.','locale 指事件发生的地点，未发生事件的地方不符合语境。')],quiz:[Q('locale',1,1,'A story’s locale is its?','setting or place','main character’s personality','ending paragraph','setting or place','locale 指故事或事件的场所。'),Q('locale',2,1,'Which could be a locale for a play?','an abandoned station where the action occurs','a costume worn by the lead','the audience’s opinion afterward','an abandoned station where the action occurs','戏剧发生的废弃车站是场景地点。'),Q('locale',3,1,'Locale is closest to?','setting','argument','instrument','setting','setting 可表示事件发生的场所。','meaning'),Q('locale',4,1,'A travel writer naming a locale gives the reader?','the place where an event or scene occurs','the price of every meal','the writer’s age','the place where an event or scene occurs','locale 提供地点信息。')]});
D('locality',{etymology:E('Locality derives from Medieval Latin localitas, from localis “of a place”; it means a particular area or the location where something is situated.','locality'),contexts:[C('locality.s1','生态调查','The rare orchid grows only in a small locality on the island’s damp northern slope.','这种稀有兰花只生长在岛屿潮湿北坡的一小片区域。','The rare orchid grows / only in a small locality / on the island’s damp northern slope.','locality.s1 指特定地区或邻近区域。','兰花只出现于岛上的某个有限区域。')],mistakes:[M('The survey called the entire continent one small locality although the species appeared in only a single valley.','The survey identified a small locality in the valley where the species occurs.','范围极大的大陆不是语境中所说的狭小特定地区。')],quiz:[Q('locality',1,1,'A locality is?','a particular area or neighborhood','a person’s opinion','a legal payment','a particular area or neighborhood','locality.s1 指某一地区。'),Q('locality',2,2,'The locality of a cave is?','the place where it is situated','the tool used to enter it','the age of its explorer','the place where it is situated','locality.s2 可指某物所在的位置。'),Q('locality',3,1,'Which phrase is natural?','a rural locality near the border','a locality of hungry to run','a locality weighs five liters','a rural locality near the border','locality 常与 rural 等地域形容词搭配。','collocation'),Q('locality',4,1,'A study of a species’ locality asks?','where it lives','how loudly it sings','who named it','where it lives','调查 locality 关注物种所在地区。')]});
D('localization',{etymology:E('Localization is formed from localize with -ation; it names the process of identifying a location or adapting a product for a particular region and language.','localization'),contexts:[C('localization.s2','软件产品','The game’s localization changed jokes, date formats, and menus so they made sense to players in Brazil.','游戏本地化调整了笑话、日期格式和菜单，使其符合巴西玩家的理解习惯。','The game’s localization changed / jokes, date formats, and menus / so they made sense / to players in Brazil.','localization.s2 指针对特定地区语言和文化调整产品内容的过程。','版本调整了语言及区域惯例，而非只做字面翻译。')],mistakes:[M('The team called its work localization although it copied every screen unchanged and left all references unfamiliar to local users.','The team localized the game by adapting text, examples, and conventions for local players.','保留所有内容不变，没有完成针对地区用户的适配。')],quiz:[Q('localization',1,1,'Software localization may adjust?','language and cultural details for a target region','the software’s processor speed only','the company’s office location only','language and cultural details for a target region','localization.s2 指软件本地化。'),Q('localization',2,1,'Localization can also refer to?','the process of finding where something is','translating every text word-for-word only','closing a regional office','the process of finding where something is','localization.s1 也可指定位过程。'),Q('localization',3,2,'A localized app for Japan might change?','date formats and examples to suit Japanese users','the laws of physics','its users’ home addresses','date formats and examples to suit Japanese users','本地化可调整区域格式和文化内容。'),Q('localization',4,2,'Which task is localization rather than basic translation?','reworking jokes and measurements for local users','replacing each word with a dictionary equivalent only','moving a server without changing user content','reworking jokes and measurements for local users','针对用户习惯改编内容属于本地化。')]});
D('localize',{etymology:E('Localize is formed from local with -ize; it means determine or restrict something to a particular place, or adapt it for a local market.','localize'),contexts:[C('localize.s1','疾病防控','Doctors localized the infection to one small wound and found no evidence that it had spread.','医生确认感染局限于一处小伤口，没有证据显示它已经扩散。','Doctors localized the infection / to one small wound / and found no evidence / that it had spread.','localize.s1 指确定某物的位置或使其局限于一处。','检查确定感染没有扩散到身体其他部位。')],mistakes:[M('The doctors localized the infection when they found it had spread through every organ and could not be tied to one site.','The doctors localized the infection when tests showed it remained confined to one wound.','已扩散全身并非局限在一处。')],quiz:[Q('localize',1,1,'To localize a leak is to?','identify or confine it to a particular place','spread it throughout the building','translate a menu','identify or confine it to a particular place','localize.s1 指查明位置或使其局限。'),Q('localize',2,1,'A doctor localizes pain by?','determining the specific area where it occurs','ignoring where it occurs','changing a patient’s language','determining the specific area where it occurs','医生定位疼痛区域。'),Q('localize',3,1,'Which use is correct?','The team localized the fault to one circuit.','The team localized the fault into yesterday.','The localize was on the shelf.','The team localized the fault to one circuit.','可说 localize something to a specific area。','collocation'),Q('localize',4,1,'To localize a fire before it spreads is to?','keep it confined to one area','carry it to every room','put out a different fire elsewhere','keep it confined to one area','localize 有使局部化、限制在一处之意。')]});
D('locally',{etymology:E('Locally is the adverb from local; it means within a limited area or in/through the nearby community.','locally'),contexts:[C('locally.s1','农产品供应','The café buys its eggs locally, from farms within twenty kilometers of the town.','这家咖啡馆在当地采购鸡蛋，供应方是距镇上二十公里以内的农场。','The café buys its eggs locally / from farms / within twenty kilometers / of the town.','locally.s1 指在有限区域内或从附近社区进行。','鸡蛋来自附近农场，而非遥远供应地。')],mistakes:[M('The shop said its goods were made locally even though every item was manufactured overseas and shipped across the ocean.','The shop said its goods were made locally because a nearby workshop produced them.','海外生产与本地生产相矛盾。')],quiz:[Q('locally',1,1,'If a shop sources produce locally, it gets it?','from nearby suppliers','only from another continent','from a fictional place','from nearby suppliers','locally 指从当地、附近取得。'),Q('locally',2,1,'A disease spreading locally is spreading?','within a limited area','through every country on earth','only in the past','within a limited area','locally 可表示局部范围内。'),Q('locally',3,1,'Which sentence uses locally as an adverb?','The theater hires musicians locally.','The local is the theater’s musician.','The locally was painted blue.','The theater hires musicians locally.','locally 修饰 hires，表示在本地招聘。'),Q('locally',4,1,'Locally is the adverb related to?','local','lobe','lobby','local','locally 由 local 加 -ly 构成。','word-formation')]});
D('locate',{etymology:E('Locate comes from Latin locare, “to place,” from locus “place”; it means find where something is or establish something in a particular position.','locate'),contexts:[C('locate.s1','搜救行动','Rescuers used the emergency signal to locate the climber before nightfall.','救援人员利用紧急信号在天黑前找到登山者。','Rescuers used the emergency signal / to locate the climber / before nightfall.','locate.s1 指查明某人或某物的确切位置。','信号帮助救援队找到登山者所在之处。'),C('locate.s2','企业选址','The company decided to locate its new laboratory near the university’s research center.','公司决定把新实验室设在大学研究中心附近。','The company decided / to locate its new laboratory / near the university’s research center.','locate.s2 指把建筑或业务设置在某个地点。','公司选择并设置了实验室的位置。')],mistakes:[M('The rescue team located the climber by refusing to use the signal and remaining unaware of the climber’s position.','The rescue team located the climber after using the signal to determine the exact position.','没有查明位置就不算 locate。')],quiz:[Q('locate',1,1,'To locate a missing key is to?','find where it is','make a copy of it','forget it deliberately','find where it is','locate.s1 指找到位置。'),Q('locate',2,2,'A firm may locate its office near a station by?','establishing the office there','searching for a lost ticket','moving the station','establishing the office there','locate.s2 指把机构设置在某处。'),Q('locate',3,1,'Which question asks someone to locate an object?','Can you tell me where the valve is?','Can you paint the valve red?','Can you repair the wall?','Can you tell me where the valve is?','查明物体所在位置对应 locate。'),Q('locate',4,1,'Which construction is standard?','locate the clinic near the station','locate the clinic of near station','locate near the clinic station','locate the clinic near the station','可说 locate a building near a place。','collocation')]});
D('location',{etymology:E('Location derives from Latin locatio, “a placing or renting,” from locare “to place”; its common sense is the particular place where something is situated or happens.','location'),contexts:[C('location.s1','拍摄计划','The producer shared the exact location of the outdoor shoot with the crew the night before.','制片人前一晚把外景拍摄的准确地点告知了剧组。','The producer shared / the exact location / of the outdoor shoot / with the crew the night before.','location.s1 指事物所在或事件发生的具体地点。','剧组需要知道外景拍摄的具体地点。')],mistakes:[M('The crew reached the location even though no place for the shoot had been selected or identified.','The crew reached the location after the producer sent them the selected site.','没有选定或识别地点就不能称为已知的 location。')],quiz:[Q('location',1,1,'The location of a meeting is?','the place where it takes place','the number of people attending','the length of the agenda','the place where it takes place','location.s1 指事件发生地点。'),Q('location',2,1,'A film crew scouting locations is looking for?','places where scenes can be shot','new actors’ surnames','a quieter soundtrack','places where scenes can be shot','拍摄团队勘景是在寻找拍摄地点。'),Q('location',3,1,'Which phrase is natural?','the exact location of the bridge','the location weighs two kilograms','the location to sleep yesterday','the exact location of the bridge','location 可与 exact 搭配表示确切位置。','collocation'),Q('location',4,1,'If a package’s location is unknown, people do not know?','where it is','who ordered it','how heavy it was originally','where it is','不知道 location 就是不知道其所在位置。')]});
D('loch',{etymology:E('Loch is a Scottish Gaelic word, from Old Irish loch, meaning a lake or inlet; in English it especially refers to a long, narrow lake in Scotland.','loch'),contexts:[C('loch.s1','苏格兰旅行','A footpath follows the eastern shore of the loch, passing a small stone pier and a row of pines.','一条小径沿着湖泊东岸延伸，经过一座小石码头和一排松树。','A footpath follows / the eastern shore of the loch / passing a small stone pier / and a row of pines.','loch 指湖泊，尤其是苏格兰的狭长湖泊。','湖岸、小码头和松林显示它是水域。')],mistakes:[M('The map labeled a dry mountain pass as a loch even though there was no lake or water inlet there.','The map labeled the long narrow Scottish lake as a loch.','loch 指湖泊或海湾状水域，不是干燥山口。')],quiz:[Q('loch',1,1,'A Scottish loch is a?','lake','mountain pass','stone cottage','lake','loch.s1 指湖泊。'),Q('loch',2,1,'Where would a boat most likely travel on a loch?','across its water','through a dry tunnel','along a railway platform','across its water','船可在湖泊水面航行。'),Q('loch',3,1,'Loch is especially associated with?','Scotland','Brazil','the Sahara','Scotland','loch 在英语中特别与苏格兰有关。'),Q('loch',4,1,'A narrow body of inland water is a?','loch','locker','lobe','loch','loch 可指狭长湖泊。')]});
D('lock',{etymology:E('Lock is an old Germanic word; it names a fastening device, the act of securing something, a canal chamber for raising boats, or a curl of hair.','lock'),contexts:[C('lock.s2','家庭安全','Please lock the back door before you leave so the latch cannot be opened from outside.','离开前请锁好后门，免得有人从外面打开门闩。','Please lock the back door / before you leave / so the latch cannot be opened / from outside.','lock.s2 作动词，表示用锁固定或使某物无法打开。','离开前要把门闩锁住。')],mistakes:[M('She locked the door by leaving the key turned so the latch stayed open and anyone could enter.','She locked the door by turning the key until the latch held it shut.','门闩保持打开无法达到锁门的效果。')],quiz:[Q('lock',1,1,'A door lock is a?','device that keeps the door fastened','rounded part of an ear','type of Scottish lake','device that keeps the door fastened','lock.s1 是固定门扇的锁具。'),Q('lock',2,2,'To lock a drawer is to?','secure it with a lock','leave it open','move it to another room','secure it with a lock','lock.s2 作动词表示锁住。'),Q('lock',3,3,'A canal lock lets boats?','change level between sections of water','store clothes in a locker','cross a dry field','change level between sections of water','lock.s3 指帮助船只升降的船闸。'),Q('lock',4,4,'A lock of hair is?','a small bunch of hair','a metal key','a canal gate','a small bunch of hair','lock.s4 可指一绺头发。')]});
D('locker',{etymology:E('Locker is formed from lock with the agent or container suffix -er; it is a small lockable compartment for storing personal belongings.','locker'),contexts:[C('locker.s1','学校生活','Ravi left his muddy boots in the locker outside the gym before entering the clean studio.','拉维进干净的练习室前，把沾满泥的靴子放在体育馆外的储物柜里。','Ravi left his muddy boots / in the locker outside the gym / before entering / the clean studio.','locker.s1 指学校、健身房等处可上锁的储物小柜。','柜子用来暂存个人物品，并可锁住。')],mistakes:[M('She stored her bag in a locker that had no compartment, door, or place to keep belongings.','She stored her bag in a locker, a small compartment that could be locked.','没有储物空间的地方不能称为储物柜。')],quiz:[Q('locker',1,1,'A locker is usually used to?','store belongings in a lockable compartment','raise a boat through a canal','hold a large public meeting','store belongings in a lockable compartment','locker.s1 指带锁储物柜。'),Q('locker',2,1,'Where might a student find a locker?','in a school hallway','in the middle of a lake','inside a flower petal','in a school hallway','学校走廊常设储物柜。'),Q('locker',3,1,'Which item would someone put in a gym locker?','a change of clothes','a whole lighthouse','a lake shore','a change of clothes','储物柜适合放衣物等个人用品。'),Q('locker',4,1,'Locker is formed from which base?','lock','loath','locality','lock','locker 由 lock 加 -er 构成。','word-formation')]});
D('locks',{etymology:E('Locks is the plural of lock; in this entry it refers to a person’s long hair, especially when it hangs in thick curls or strands.','locks'),contexts:[C('locks.s1','人物描写','Her dark locks were pinned back for the ceremony, but a few curls escaped around her face.','仪式上她把深色长发别在脑后，但仍有几缕卷发垂在脸旁。','Her dark locks / were pinned back / for the ceremony / but a few curls escaped.','locks.s1 指人的头发，常带有长发或卷发的意味。','语境中的 curls 和 pinned-back hair 表明 locks 指发丝。')],mistakes:[M('The portrait described his locks as short, straight hairless skin above the ears.','The portrait described his locks as long curls falling past his shoulders.','没有头发的皮肤不能称为 locks。')],quiz:[Q('locks',1,1,'In “her golden locks,” locks means?','her hair','door fasteners','canal chambers','her hair','locks.s1 指长发或卷发。'),Q('locks',2,1,'Which phrase uses locks in the hair sense?','She brushed her silver locks.','She changed levels through the locks.','She left the keys in the locks.','She brushed her silver locks.','brush 与头发义的 locks 搭配。'),Q('locks',3,1,'A lock of hair is a?','small bunch of hair','type of door key','nearby pub','small bunch of hair','lock 可指一绺头发。'),Q('locks',4,1,'In a poem, “flowing locks” most likely describes?','long hair','a set of canal gates','a row of storage cabinets','long hair','flowing 通常描写长发。')]});
D('locomote',{etymology:E('Locomote is a back-formation from locomotion, combining Latin locus “place” and motio “movement”; it means move from place to place by one’s own motion.','locomote'),contexts:[C('locomote.s1','动物行为','The injured beetle could still locomote, although it moved much more slowly than the others.','这只受伤的甲虫仍能自行移动，虽然速度比其他甲虫慢得多。','The injured beetle could still locomote / although it moved / much more slowly / than the others.','locomote.s1 指生物靠自身力量从一处移动到另一处。','甲虫依靠身体运动完成位置改变。')],mistakes:[M('The beetle locomoted by remaining motionless in the same spot throughout the observation.','The beetle locomoted by crawling from one leaf to another.','完全静止没有发生位置移动。')],quiz:[Q('locomote',1,1,'An animal that can locomote can?','move from place to place','change color at will','make a dictionary','move from place to place','locomote.s1 指移动。'),Q('locomote',2,2,'A self-propelled robot can locomote by?','moving under its own power','being stored in a locker','being described in a lexicon','moving under its own power','locomote.s2 可用于机器或微生物的自行移行。'),Q('locomote',3,1,'Which sentence uses locomote correctly?','The larvae locomote across the damp surface.','The larvae locomote a dictionary.','The locomote was blue.','The larvae locomote across the damp surface.','locomote 是不及物动词，描述移动。','grammar'),Q('locomote',4,1,'Locomote is related in meaning to?','move','lobby','loathe','move','locomote 表示移动。','meaning')]});
D('locomotion',{etymology:E('Locomotion combines Latin locus “place” and motio “movement”; it means movement from one place to another, by walking or another means.','locomotion'),contexts:[C('locomotion.s1','生物学课堂','The lesson compared the fish’s swimming locomotion with the frog’s powerful jumps.','这节课比较了鱼类的游泳运动和青蛙有力的跳跃。','The lesson compared / the fish’s swimming locomotion / with / the frog’s powerful jumps.','locomotion 指从一处到另一处的运动方式或过程。','游泳和跳跃都是生物改变位置的方式。')],mistakes:[M('The report described locomotion as the animal’s complete stillness in one place.','The report described locomotion as the animal’s movement across the enclosure.','locomotion 是移动而不是静止。')],quiz:[Q('locomotion',1,1,'Locomotion is?','movement from place to place','a small roof space','a mineral deposit','movement from place to place','locomotion.s1 指位移运动。'),Q('locomotion',2,1,'Which is a form of animal locomotion?','a seal swimming to another rock','a seal resting without moving','a seal changing its color','a seal swimming to another rock','游到另一处属于位移运动。'),Q('locomotion',3,1,'A study of locomotion would examine how animals?','move','record ship logs','form minerals','move','locomotion 关注运动方式。'),Q('locomotion',4,1,'Locomotion is related to the verb?','locomote','lodge','loath','locomote','locomotion 与 locomote 同词族。','word-formation')]});
D('locomotive',{etymology:E('Locomotive combines Latin locus “place” with motivus “moving”; as a noun it is a railway engine, and as an adjective it relates to movement.','locomotive'),contexts:[C('locomotive.s1','铁路运输','The locomotive pulled a line of freight cars uphill toward the mountain tunnel.','机车牵引着一列货车爬坡，驶向山间隧道。','The locomotive pulled / a line of freight cars / uphill / toward the mountain tunnel.','locomotive.s1 指牵引列车车厢行驶的铁路机车。','机车为货运车厢提供牵引力。')],mistakes:[M('The locomotive was a passenger coach that had no engine and could not pull any cars.','The locomotive was the powered engine at the front of the train.','没有动力、不能牵引车厢的车厢不是机车。')],quiz:[Q('locomotive',1,1,'A railway locomotive is the?','engine that pulls the train','last empty freight car','station waiting room','engine that pulls the train','locomotive.s1 指火车头或机车。'),Q('locomotive',2,2,'A locomotive function concerns?','movement from place to place','keeping a roof dry','measuring the age of a tree','movement from place to place','locomotive.s2 是与移动有关的形容词。'),Q('locomotive',3,1,'Which part usually provides power to pull rail cars?','the locomotive','the platform clock','the ticket office','the locomotive','机车牵引列车车厢。'),Q('locomotive',4,1,'A locomotive belongs to which transport system?','railway','canal only','air traffic control','railway','locomotive 是铁路机车。')]});
D('locomotor',{etymology:E('Locomotor is formed from locomotion with -or; as an adjective it concerns movement, and as a noun it can name a body part used for movement.','locomotor'),contexts:[C('locomotor.s2','动物解剖','The laboratory diagram labels each locomotor organ that helps the animal push itself through water.','实验室图示标出了帮助这种动物在水中推进的各个运动器官。','The laboratory diagram labels / each locomotor organ / that helps the animal / push itself through water.','locomotor.s2 作名词，指产生运动的身体部分或器官。','该器官帮助动物推进身体。')],mistakes:[M('The anatomy chart called a motion-producing limb a locomotor organ but said it played no role in movement.','The chart identified the limb as a locomotor organ because it produces movement.','产生运动的肢体正是运动器官。')],quiz:[Q('locomotor',1,1,'A locomotor system is concerned with?','movement','digestion only','word spelling','movement','locomotor.s1 表示与运动有关。'),Q('locomotor',2,2,'A locomotor organ helps an animal?','move','digest every food','record its age','move','locomotor.s2 指产生运动的器官。'),Q('locomotor',3,1,'Which may be a locomotor organ?','a leg used for walking','a feather used only for color','a tooth used for chewing','a leg used for walking','用于行走的腿帮助动物运动。'),Q('locomotor',4,1,'Locomotor is related to?','locomotion','locality','logarithm','locomotion','locomotor 与 locomotion 同词族。','word-formation')]});
D('locoweed',{etymology:E('Locoweed is formed from loco, “mad,” and weed; the name refers to several plants whose toxins can cause abnormal behavior or illness in grazing animals.','locoweed'),contexts:[C('locoweed.s1','牧场管理','The rancher fenced off the patch of locoweed after a veterinarian warned that grazing animals could be poisoned.','兽医提醒牧场主放牧动物可能中毒后，牧场主便围起了那片疯草。','The rancher fenced off / the patch of locoweed / after a veterinarian warned / that grazing animals could be poisoned.','locoweed 指含有可使牲畜神经系统受影响的毒素的植物。','牧场围挡是为避免牲畜啃食有毒植物。')],mistakes:[M('The rancher encouraged the herd to graze on locoweed because the plant was certified harmless to livestock.','The rancher kept livestock away from locoweed because it can be toxic to grazing animals.','locoweed 可能毒害牲畜，不应把它说成已证实无害。')],quiz:[Q('locoweed',1,1,'Locoweed is a?','plant that can poison livestock','type of railway engine','kind of natural magnet','plant that can poison livestock','locoweed.s1 指可能毒害牲畜的植物。'),Q('locoweed',2,1,'Why might a rancher fence off locoweed?','to keep grazing animals from eating it','to help animals reach it more easily','to build a railway around it','to keep grazing animals from eating it','围起疯草是为防止牲畜误食。'),Q('locoweed',3,1,'The word locoweed is associated with?','abnormal effects on livestock','a local pub','a canal gate','abnormal effects on livestock','名称与植物对牲畜的异常影响有关。'),Q('locoweed',4,1,'Locoweed is best classified as a?','plant','mineral','piece of machinery','plant','locoweed 是植物。')]});
D('locust',{etymology:E('Locust came through Old French from Latin locusta, a name for a grasshopper or lobster; it refers to a short-horned grasshopper, especially one that forms destructive swarms.','locust'),contexts:[C('locust.s1','农业灾害','A dense locust swarm crossed the valley and stripped leaves from several fields in a single afternoon.','一大群蝗虫飞过山谷，一个下午就把几片田地的叶子吃光了。','A dense locust swarm / crossed the valley / and stripped leaves / from several fields in a single afternoon.','locust 指短角蝗虫，尤其是成群迁飞并造成破坏的种类。','成群蝗虫迅速啃食农田植被。')],mistakes:[M('The farmers feared the locust swarm because the insects ate no plants and remained harmlessly underground.','The farmers feared the locust swarm because it could consume crops across the valley.','不取食植物、停留地下的描述与蝗虫群的破坏性不符。')],quiz:[Q('locust',1,1,'A locust is a kind of?','grasshopper','sea turtle','roof space','grasshopper','locust.s1 是蝗虫。'),Q('locust',2,1,'A locust swarm can damage?','crops by eating vegetation','railway engines','stone deposits','crops by eating vegetation','蝗虫群可毁坏农作物。'),Q('locust',3,1,'Which phrase is associated with locust?','a swarm crossing farmland','a lock on a locker','a lobe of the ear','a swarm crossing farmland','locust 常以群体出现并迁飞。'),Q('locust',4,1,'A locust is an insect, not a?','mammal','grasshopper','crop pest','mammal','蝗虫属于昆虫而非哺乳动物。')]});
D('lode',{etymology:E('Lode is an old mining term related to a vein or course; it means a mineral-bearing deposit running through surrounding rock.','lode'),contexts:[C('lode.s1','地质勘探','The survey team traced a narrow lode of copper-bearing ore through the exposed rock face.','勘测队沿着裸露岩壁追踪一条含铜矿石的狭窄矿脉。','The survey team traced / a narrow lode of copper-bearing ore / through / the exposed rock face.','lode 指穿过周围岩石的矿脉或矿床。','铜矿石沿岩层呈脉状延伸。')],mistakes:[M('The geologist called a vein of ore a lode even though no mineral deposit ran through the surrounding rock.','The geologist mapped a lode where mineral-bearing rock formed a continuous vein.','没有矿物沉积的岩层不构成矿脉。')],quiz:[Q('lode',1,1,'A lode is a?','mineral deposit running through rock','small room under a roof','railway engine','mineral deposit running through rock','lode.s1 指矿脉。'),Q('lode',2,1,'A prospector searching for a gold lode is looking for?','a vein of gold-bearing ore','a flock of seabirds','a place to rent a room','a vein of gold-bearing ore','找金矿脉就是寻找含金矿石带。'),Q('lode',3,1,'Which field commonly uses lode?','mining geology','restaurant cooking','music performance','mining geology','lode 是采矿与地质用语。'),Q('lode',4,1,'A lode runs through surrounding?','rock','hair','water only','rock','矿脉穿过周围岩石。')]});
D('lodestone',{etymology:E('Lodestone combines lode with stone; it names naturally magnetized magnetite that attracts iron and historically served as a compass material.','lodestone'),contexts:[C('lodestone.s1','地球科学','The student brought a lodestone close to the iron filings and watched them gather around one end.','学生把天然磁石靠近铁屑，看着铁屑聚集到它的一端。','The student brought a lodestone / close to the iron filings / and watched them gather / around one end.','lodestone 是天然具有磁性的石头，能够吸引铁。','铁屑被石头的磁性吸引。')],mistakes:[M('The lodestone repelled every iron filing because it had no magnetism and could attract only paper.','The lodestone attracted the iron filings because it was naturally magnetized.','天然磁石的核心特征是磁性吸引铁。')],quiz:[Q('lodestone',1,1,'A lodestone is a naturally magnetized?','stone','wooden log','canal gate','stone','lodestone.s1 指天然磁石。'),Q('lodestone',2,1,'What would a lodestone attract?','iron filings','dry leaves only','a spoken sentence','iron filings','lodestone 能吸引铁。'),Q('lodestone',3,1,'Before modern compasses, lodestone was useful because it?','could act as a magnet','could provide lodging','could measure logarithms','could act as a magnet','磁石可用来制指南针或显示磁性。'),Q('lodestone',4,1,'Lodestone is most closely connected with?','magnetism','locomotion','logging','magnetism','lodestone 的主要性质是磁性。')]});
D('lodge',{etymology:E('Lodge comes through Old French from Germanic roots for a shelter; it can mean stay as a paying guest, become stuck, submit a formal complaint, or name a small house or entrance room.','lodge'),contexts:[C('lodge.s1','短期住宿','The researchers lodged at a family-run inn while they collected samples from the marsh.','研究人员采集沼泽样本期间，住在一家家庭经营的小旅馆里。','The researchers lodged / at a family-run inn / while they collected samples / from the marsh.','lodge.s1 作动词，表示寄宿或投宿。','研究人员在旅馆短住。'),C('lodge.s3','正式申诉','Several tenants lodged a complaint with the housing office about the unsafe stairwell.','几名租户就不安全的楼梯间向住房办公室正式提出投诉。','Several tenants lodged a complaint / with the housing office / about the unsafe stairwell.','lodge.s3 表示正式提出投诉、申诉或陈述。','租户向主管机构正式提出问题。')],mistakes:[M('The tenants lodged a complaint by withholding it from the housing office and never making a formal report.','The tenants lodged a complaint by submitting it to the housing office.','未向机构提交投诉，就不算正式提出申诉。')],quiz:[Q('lodge',1,1,'To lodge at an inn is to?','stay there as a guest','work as a logger','close a canal gate','stay there as a guest','lodge.s1 指投宿。'),Q('lodge',2,2,'A splinter lodged in a finger has?','become stuck there','been rented out','been made into a log','become stuck there','lodge.s2 表示卡住或嵌入。'),Q('lodge',3,3,'To lodge a formal complaint is to?','submit it officially','hide it forever','change its location on a map','submit it officially','lodge.s3 指正式提出申诉。'),Q('lodge',4,4,'A hunting lodge is a?','small house or shelter','railway locomotive','mineral vein','small house or shelter','lodge.s4 可指小屋。')]});
D('lodger',{etymology:E('Lodger is formed from lodge with -er; it names a person who rents a room in someone else’s home or property.','lodger'),contexts:[C('lodger.s1','房屋租赁','The lodger paid for the attic room each month and shared the kitchen with the homeowner.','房客每月为阁楼房间付租金，并与房主共用厨房。','The lodger paid / for the attic room / each month / and shared the kitchen with the homeowner.','lodger 指在他人住宅中租住一个房间的人。','房客支付房租并住在房主的房屋内。')],mistakes:[M('The homeowner called a lodger someone who owned the entire house and rented no room from anyone.','The homeowner called the person renting the attic room a lodger.','lodger 是租住房间的人，不是房屋所有者。')],quiz:[Q('lodger',1,1,'A lodger is someone who?','rents a room in another person’s property','owns a railway engine','records a ship’s journey','rents a room in another person’s property','lodger.s1 指房客。'),Q('lodger',2,1,'Which arrangement makes someone a lodger?','paying to live in a spare room in a host’s home','staying one hour in a public lobby','owning a detached house outright','paying to live in a spare room in a host’s home','在他人家租住空房间符合 lodger 的定义。'),Q('lodger',3,1,'Lodger is formed from?','lodge','lode','locust','lodge','lodger 由 lodge 加 -er 构成。','word-formation'),Q('lodger',4,1,'A lodger usually pays for?','a room to live in','a mineral deposit','a canal lock','a room to live in','lodger 通常租住一个房间。')]});
D('lodging',{etymology:E('Lodging comes from lodge with the noun-forming -ing; it refers to a temporary place to stay or the arrangement of staying there.','lodging'),contexts:[C('lodging.s1','旅行安排','We booked inexpensive lodging near the station because the conference ended after the last train home.','我们在车站附近预订了便宜的住宿，因为会议结束时回家的末班车已经开走。','We booked inexpensive lodging / near the station / because the conference ended / after the last train home.','lodging 指短期住宿的地方或住宿安排。','旅客预订临时住处以便参加会议。')],mistakes:[M('The hikers found lodging by sleeping outdoors without shelter or any place to stay.','The hikers found lodging in a small guesthouse near the trail.','没有住处或住宿安排就不能说找到了 lodging。')],quiz:[Q('lodging',1,1,'Lodging means?','a place to stay temporarily','a type of mineral','a train engine','a place to stay temporarily','lodging.s1 指临时住宿。'),Q('lodging',2,1,'A traveler looking for lodging needs?','somewhere to sleep','a way to cut a tree','a word’s logarithm','somewhere to sleep','住宿是供旅客暂住的地方。'),Q('lodging',3,1,'Which phrase is natural?','affordable lodging near the airport','lodging a tree into a number','lodging weighs two kilometers','affordable lodging near the airport','lodging 常与 affordable 和地点搭配。','collocation'),Q('lodging',4,1,'Lodging is related to the verb?','lodge','log','lobe','lodge','lodging 是 lodge 的名词形式。','word-formation')]});
D('loess',{etymology:E('Loess is borrowed from German Löss, a regional name for fine wind-deposited sediment; it often forms fertile yellowish soil.','loess'),contexts:[C('loess.s1','地貌研究','The river cut a steep bank through the thick loess, exposing layers of fine yellow-brown silt.','河流切穿厚厚的黄土层，露出一层层细腻的黄褐色粉砂。','The river cut a steep bank / through the thick loess / exposing layers / of fine yellow-brown silt.','loess 指风力沉积形成的粉砂性黄土。','细颗粒沉积层被河流侵蚀后显露出来。')],mistakes:[M('The geologist identified the coarse volcanic boulders as loess, though they were not fine wind-deposited sediment.','The geologist identified the fine windblown silt as loess.','大块火山砾石不符合黄土的细颗粒风成沉积特征。')],quiz:[Q('loess',1,1,'Loess is mainly?','fine wind-deposited sediment','a kind of tree trunk','a sea turtle','fine wind-deposited sediment','loess.s1 指风成粉砂或黄土。'),Q('loess',2,1,'Loess commonly forms?','yellowish fertile soil','metal locks','a railway engine','yellowish fertile soil','黄土通常可形成肥沃土壤。'),Q('loess',3,1,'Which process deposits loess?','wind carrying fine silt','a lobster digging a burrow','a train pulling freight','wind carrying fine silt','风搬运细粉砂形成黄土。'),Q('loess',4,1,'Loess is a geological?','sediment','animal','building entrance','sediment','loess 属地质沉积物。')]});
D('loft',{etymology:E('Loft entered English from Old Norse lopt, “air or upper room”; it means an attic-like space directly beneath a roof, often used for storage.','loft'),contexts:[C('loft.s1','住宅空间','They stored suitcases in the loft above the bedrooms, where the sloping roof left little standing room.','他们把行李箱存放在卧室上方的阁楼里，倾斜的屋顶使那里几乎无法直立。','They stored suitcases / in the loft above the bedrooms / where the sloping roof / left little standing room.','loft.s1 指屋顶下方的阁楼空间，常用于储物。','空间位于卧室上方的斜屋顶下。')],mistakes:[M('The family called the basement beneath the foundations a loft even though it was below ground and far from the roof.','The family called the storage space directly beneath the roof a loft.','loft 位于屋顶下方，不是地下室。')],quiz:[Q('loft',1,1,'A loft is usually?','a space just below a roof','a room beneath a lake','a canal gate','a space just below a roof','loft.s1 指阁楼。'),Q('loft',2,1,'Which item might be stored in a loft?','old suitcases','a railway locomotive','a swarm of locusts','old suitcases','阁楼常用于储存不常用物品。'),Q('loft',3,1,'A loft is more likely above the?','top floor','foundation basement','riverbed','top floor','阁楼位于较高处、屋顶之下。'),Q('loft',4,1,'Which is a loft?','an attic-like room under a sloped roof','a mineral vein through rock','a place where boats change canal levels','an attic-like room under a sloped roof','屋顶下的阁楼式空间是 loft。')]});
D('lofty',{etymology:E('Lofty is formed from loft with -y; it can describe great physical height, noble ideals, or an arrogant manner.','lofty'),contexts:[C('lofty.s2','公益倡议','Their lofty goal was to provide clean water to every village in the region.','他们崇高的目标是为该地区的每个村庄提供洁净饮水。','Their lofty goal / was to provide clean water / to every village / in the region.','lofty.s2 比喻崇高、值得敬佩的理想或目标。','目标关注整个地区居民的基本需要。')],mistakes:[M('The group described its goal as lofty even though it aimed only to preserve an unfair privilege for its leaders.','The group described its goal as lofty because it sought clean water for every village.','只维护少数人的不公平特权不构成崇高目标。')],quiz:[Q('lofty',1,1,'A lofty mountain peak is?','very high','below sea level','made of paper','very high','lofty.s1 表示高耸的。'),Q('lofty',2,2,'A lofty moral ideal is?','noble and admirable','small and practical only','physically underground','noble and admirable','lofty.s2 表示崇高的。'),Q('lofty',3,3,'A lofty manner may seem?','arrogant or superior','friendly and humble','completely invisible','arrogant or superior','lofty.s3 也可形容傲慢。'),Q('lofty',4,2,'Which is a lofty aim?','ending preventable hunger across the region','winning a minor argument by cheating','keeping needed medicine from patients','ending preventable hunger across the region','宏大且利他的目标可称为 lofty。')]});
D('log',{etymology:E('Log comes from an older word for a block of wood and later gained record-keeping and mathematical senses; it can also be a verb meaning record or travel a distance.','log'),contexts:[C('log.s2','航海记录','The captain entered the sudden change in wind direction in the ship’s log.','船长把风向突然改变的情况记入了船舶航海日志。','The captain entered / the sudden change in wind direction / in the ship’s log.','log.s2 指记录事件的正式日志或航行记录。','船长把航行中发生的情况写入官方记录。'),C('log.s3','设备维护','The technician logged each restart so the team could compare failures across the week.','技术人员记录了每次重启，以便团队比较这一周内出现的故障。','The technician logged each restart / so the team could compare / failures / across the week.','log.s3 作动词，表示写入正式记录，也可表示行进一段距离。','重启情况逐一记入记录。')],mistakes:[M('The captain kept a ship’s log by throwing away every note and recording none of the voyage events.','The captain kept a ship’s log by recording the vessel’s course, weather, and incidents.','不记录航行信息与维护日志的含义相反。')],quiz:[Q('log',1,1,'A fallen tree trunk may be called a?','log','lobe','lodge','log','log.s1 指原木。'),Q('log',2,2,'A ship’s log contains?','an official record of the voyage','the crew’s storage lockers','a list of nearby pubs','an official record of the voyage','log.s2 是航行记录。'),Q('log',3,3,'To log a repair is to?','record it officially','turn it into a tree','move it through a canal','record it officially','log.s3 作动词指记录。'),Q('log',4,4,'In mathematics, a log is a?','logarithm','wooden beam','large turtle','logarithm','log.s4 是 logarithm 的缩略说法。','word-formation')]});
D('logarithm',{etymology:E('Logarithm was coined from Greek logos “ratio” and arithmos “number”; it names the exponent to which a base must be raised to produce a given number.','logarithm'),contexts:[C('logarithm.s1','数学课堂','Because ten raised to the third power is one thousand, the base-ten logarithm of one thousand is three.','因为十的三次方等于一千，所以一千的常用对数是三。','Because ten raised to the third power is one thousand / the base-ten logarithm / of one thousand / is three.','logarithm 指为得到某数，底数需要取的指数。','10³=1000，因此以10为底时指数是3。')],mistakes:[M('The student said the base-ten logarithm of one thousand was five even though ten to the third power equals one thousand.','The student calculated the base-ten logarithm of one thousand as three.','对数是对应的指数，10³而不是10⁵等于1000。')],quiz:[Q('logarithm',1,1,'A logarithm tells you?','what exponent produces a number from a base','how many letters a word has','where a lake is located','what exponent produces a number from a base','logarithm.s1 指底数所需的指数。'),Q('logarithm',2,1,'Since 2³ = 8, the base-2 logarithm of 8 is?','3','2','8','3','对数值是使2得到8的指数3。'),Q('logarithm',3,1,'Which notation commonly abbreviates logarithm?','log','lodge','lode','log','log 是 logarithm 的常见缩写。','word-formation'),Q('logarithm',4,1,'A logarithm problem is most likely part of?','mathematics','housing rental','animal migration','mathematics','logarithm 是数学概念。')]});
D('logger',{etymology:E('Logger is formed from log with -er; it names a worker who cuts down trees and prepares them for timber.','logger'),contexts:[C('logger.s1','林业工作','The logger marked the trees scheduled for removal and checked that the crew stayed outside the protected grove.','伐木工人标记了计划砍伐的树木，并确认工人没有进入保护林。','The logger marked the trees / scheduled for removal / and checked / that the crew stayed outside the protected grove.','logger.s1 指砍伐树木、准备木材的工人。','工人标记要砍伐的树木并管理伐木作业。')],mistakes:[M('The logger planted no trees and never handled timber, but the report called her a logger solely because she sold vegetables.','The logger felled trees and prepared the timber for transport.','只卖蔬菜不属于伐木工人的工作。')],quiz:[Q('logger',1,1,'A logger works with?','felling trees for timber','editing mathematical proofs','raising boats in a canal','felling trees for timber','logger.s1 指伐木工。'),Q('logger',2,1,'Where might a logger work?','in a managed forest','inside a ship’s logbook','in a hotel lobby','in a managed forest','伐木工人在林区作业。'),Q('logger',3,1,'Logger is formed from?','log','lobe','local','log','logger 由 log 加 -er 构成。','word-formation'),Q('logger',4,1,'A logger’s work produces?','timber','lodging','locomotion','timber','伐木为木材加工提供原料。')]});
D('loggerhead',{etymology:E('Loggerhead is an old compound of log and head; it can mean a stupid or stubborn person, and it is also the name of a large-headed sea turtle.','loggerhead'),contexts:[C('loggerhead.s2','海龟保护','The loggerhead surfaced beside the research boat, then disappeared beneath the waves.','这只蠵龟在研究船旁浮出水面，随后又消失在海浪之下。','The loggerhead surfaced / beside the research boat / then disappeared / beneath the waves.','loggerhead.s2 指头部较大的海龟——蠵龟。','它浮出海面又潜入水中，符合海龟的活动。')],mistakes:[M('The marine biologist identified a loggerhead as a small freshwater fish with no shell.','The marine biologist identified the large-headed sea turtle as a loggerhead.','loggerhead 是海龟，不是无壳淡水鱼。')],quiz:[Q('loggerhead',1,1,'Calling someone a loggerhead may mean calling them?','a stupid or stubborn person','a railway conductor','a local resident','a stupid or stubborn person','loggerhead.s1 可指蠢人或固执的人。'),Q('loggerhead',2,2,'A loggerhead turtle is?','a large-headed sea turtle','a type of tree worker','a mathematical exponent','a large-headed sea turtle','loggerhead.s2 指蠵龟。'),Q('loggerhead',3,2,'Which habitat best fits a loggerhead turtle?','the ocean','a roof loft','a dry mine tunnel','the ocean','蠵龟是海龟，生活在海洋。'),Q('loggerhead',4,1,'Which sentence uses the insult sense?','Stop acting like a loggerhead and listen to the instructions.','The loggerhead swam past the reef.','A loggerhead was tagged near the coast.','Stop acting like a loggerhead and listen to the instructions.','该句用 loggerhead 指愚笨或固执的人。')]});
D('logic',{etymology:E('Logic comes from Greek logikē, “the science of reasoning,” from logos “reason”; it means sound reasoning or the principles by which ideas follow.','logic'),contexts:[C('logic.s1','论证评估','The reviewer questioned the logic of the plan because its conclusion did not follow from the evidence.','审稿人质疑计划的推理，因为结论并非由证据推出。','The reviewer questioned / the logic of the plan / because its conclusion / did not follow from the evidence.','logic.s1 指推理方式或正确推理的原则。','结论和证据之间缺少合理的推导关系。')],mistakes:[M('The argument had sound logic because its conclusion contradicted every premise and relied on no evidence.','The argument had sound logic because its conclusion followed from its premises.','结论若与前提矛盾，就没有 sound logic。')],quiz:[Q('logic',1,1,'Logic is concerned with?','valid reasoning','renting a room','a kind of soil','valid reasoning','logic.s1 指逻辑推理。'),Q('logic',2,2,'“There is logic to her decision” means it?','makes good sense','is a railway engine','is made of timber','makes good sense','logic.s2 可指道理或合理性。'),Q('logic',3,1,'A conclusion that follows from its evidence shows?','sound logic','a loess deposit','a locust swarm','sound logic','结论由证据支持，体现合理推理。'),Q('logic',4,1,'Logic is a branch of?','reasoning and argument','forestry only','marine biology only','reasoning and argument','logic 研究推理原则。')]});
D('logical',{etymology:E('Logical is formed from logic with -al; it describes reasoning that follows clearly or relates to the study of reasoning.','logical'),contexts:[C('logical.s1','决策讨论','Given the repeated delays, choosing a different supplier was the logical next step.','考虑到一再延误，改选供应商是合乎逻辑的下一步。','Given the repeated delays / choosing a different supplier / was the logical next step.','logical.s1 形容符合清晰推理或逻辑原则的。','供应商多次延误，因此更换供应商是合理推断。')],mistakes:[M('It was logical to keep the unreliable supplier because repeated missed deadlines proved that it always delivered on time.','It was logical to seek another supplier after repeated missed deadlines.','多次延误不能证明供应商总能准时交付。')],quiz:[Q('logical',1,1,'A logical conclusion?','follows from the available reasons','contradicts all the evidence','is chosen at random','follows from the available reasons','logical.s1 指推理清晰合理。'),Q('logical',2,1,'Which decision is logical?','wearing a coat after the forecast predicts freezing rain','leaving the windows open during a snowstorm for warmth','ignoring a tested evacuation alarm','wearing a coat after the forecast predicts freezing rain','根据天气预报穿外套是合乎逻辑的。'),Q('logical',3,1,'Logical is the adjective related to?','logic','lodge','loess','logic','logical 由 logic 加 -al 构成。','word-formation'),Q('logical',4,1,'A logical argument should have?','a conclusion supported by its premises','a conclusion unrelated to its reasons','only emotionally charged slogans','a conclusion supported by its premises','论点应由前提合理支持。')]});
D('logically',{etymology:E('Logically is the adverb from logical; it means in a way that follows reason or a consistent argument.','logically'),contexts:[C('logically.s1','问题分析','The team reasoned logically from the test results and ruled out the component that had passed every check.','团队根据测试结果进行合乎逻辑的推理，排除了每项检查都通过的部件。','The team reasoned logically / from the test results / and ruled out / the component that had passed every check.','logically.s1 表示依照推理、连贯论证的方式。','测试证据支持排除已通过检查的部件。')],mistakes:[M('She argued logically by reaching a conclusion that had no connection to her evidence or stated premises.','She argued logically by showing how each piece of evidence supported her conclusion.','结论与证据无关就不是合乎逻辑地论证。')],quiz:[Q('logically',1,1,'To reason logically is to reason?','according to consistent steps','by changing conclusions randomly','without considering evidence','according to consistent steps','logically.s1 指合乎逻辑地。'),Q('logically',2,1,'Which sentence uses logically as an adverb?','The analyst logically ruled out the failed sensor.','The analyst was a logically in the room.','The logically weighed five pounds.','The analyst logically ruled out the failed sensor.','logically 修饰 ruled out，说明推理方式。'),Q('logically',3,1,'Logically is formed from?','logical','logger','lobe','logical','logically 由 logical 加 -ly 构成。','word-formation'),Q('logically',4,1,'If one fact logically leads to a conclusion, the conclusion?','follows from that fact by reason','is unrelated to the fact','must be a guess','follows from that fact by reason','逻辑结论由事实合理推出。')]});
D('login',{etymology:E('Login combines log, “record,” with in; it names the act of gaining access to a computer system or the username used for that access.','login'),contexts:[C('login.s1','网络安全','After three failed login attempts, the account was temporarily locked to prevent guessing.','连续三次登录失败后，账户被暂时锁定，以防有人猜测密码。','After three failed login attempts / the account was temporarily locked / to prevent / guessing.','login.s1 指登录系统的过程，也可指用于登录的名称或凭据。','连续失败的登录尝试触发了账户保护措施。')],mistakes:[M('The administrator called a successful sign-out a login even though the user had left the system and gained no access.','The administrator recorded the successful sign-in as a login.','退出系统并未进入账户，不能称为登录。')],quiz:[Q('login',1,1,'A login is the act of?','signing in to a system','leaving a system','changing a screen’s logo','signing in to a system','login.s1 指登录操作。'),Q('login',2,1,'A login may also refer to?','the name used to access an account','a long-distance call','a type of lake','the name used to access an account','login 也可指登录名。'),Q('login',3,1,'Which phrase is natural?','enter your login details','enter your login weather','enter your login by the lake','enter your login details','登录时需要输入登录信息。','collocation'),Q('login',4,1,'If a login fails, the user usually?','does not gain access','has already logged out successfully','changes the company logo','does not gain access','登录失败意味着没有成功进入系统。')]});
D('logistics',{etymology:E('Logistics entered English through French from Greek logistikos, “skilled in calculation”; it covers organizing supplies and transport, and the practical arrangements for an event.','logistics'),contexts:[C('logistics.s2','学术会议','The conference team finalized the logistics, including room access, captioning, meal delivery, and speaker transport.','会议团队敲定了各项组织安排，包括会场出入、字幕服务、餐食配送和讲者接送。','The conference team finalized the logistics / including room access, captioning, meal delivery, / and speaker transport.','logistics.s2 指复杂活动的实际组织安排。','团队统筹了场地、服务、饮食和交通。')],mistakes:[M('The event’s logistics were complete even though nobody had arranged a venue, transport, meals, or equipment.','The event’s logistics were complete after the team arranged its venue, transport, meals, and equipment.','未安排关键环节就不能称活动后勤已落实。')],quiz:[Q('logistics',1,1,'Military logistics includes arranging?','supplies and transport','only the design of a logo','the length of a coastline','supplies and transport','logistics.s1 指物资、运输与后勤组织。'),Q('logistics',2,2,'Conference logistics might cover?','rooms, meals, and travel arrangements','the dictionary definition of the keynote','a speaker’s childhood only','rooms, meals, and travel arrangements','logistics.s2 指活动的具体组织工作。'),Q('logistics',3,2,'Which phrase is natural?','sort out the logistics','logistics to be long-haired','logistics a stone','sort out the logistics','常说 sort out the logistics 来表示安排实际事务。','collocation'),Q('logistics',4,1,'A logistics coordinator is most concerned with?','how people and materials get where they need to be','choosing a novel’s ending','measuring a mineral’s hardness','how people and materials get where they need to be','后勤协调关注人员与物资的实际流转。')]});
D('logo',{etymology:E('Logo is shortened from logogram or logotype, terms built from Greek logos “word” and typos “impression”; it is a graphic mark identifying an organization or product.','logo'),contexts:[C('logo.s1','品牌设计','The museum placed its new logo on tickets, staff badges, and the entrance sign.','博物馆把新标识印在门票、员工徽章和入口标牌上。','The museum placed its new logo / on tickets, staff badges, / and the entrance sign.','logo.s1 指代表公司或机构的印刷图形标识。','同一图形用于不同物料来识别博物馆。')],mistakes:[M('The museum’s logo was a long paragraph of unedited instructions rather than a recognizable identifying mark.','The museum’s logo was a distinctive graphic symbol printed on its materials.','logo 通常是用于识别的图形标记，不是整段说明文字。')],quiz:[Q('logo',1,1,'A company logo helps people?','identify the company','measure a train’s speed','find a mineral vein','identify the company','logo.s1 是识别机构的标识。'),Q('logo',2,2,'A small mark printed on a product may be its?','logo','logistics','locomotion','logo','logo.s2 指产品上的图形标记。'),Q('logo',3,1,'Which item is most likely a logo?','a distinctive graphic symbol on a shop sign','a list of shipping arrangements','a mathematical exponent','a distinctive graphic symbol on a shop sign','标牌上的识别图案属于 logo。'),Q('logo',4,1,'A logo is primarily used for?','visual identification','recording a voyage','storing clothes','visual identification','标识的主要作用是视觉识别。')]});
D('loiter',{etymology:E('Loiter is of uncertain origin; it has long meant linger or move slowly without an obvious purpose, especially in a public place.','loiter'),contexts:[C('loiter.s1','公共场所','Security asked the group not to loiter beside the emergency exit, where they were blocking a clear route.','保安请那群人不要在紧急出口旁逗留，因为他们挡住了通道。','Security asked the group / not to loiter / beside the emergency exit / where they were blocking a clear route.','loiter 指没有明显目的地在公共场所闲逛或逗留。','人群在出口附近久留并妨碍通行。')],mistakes:[M('The visitors loitered in the station by boarding their train immediately and leaving the building without delay.','The visitors loitered in the station by lingering near the entrance without a clear purpose.','立即离开与逗留相反。')],quiz:[Q('loiter',1,1,'To loiter outside a shop is to?','linger there without a clear purpose','buy it quickly','repair its sign','linger there without a clear purpose','loiter.s1 指闲逛或逗留。'),Q('loiter',2,1,'Which behavior might be described as loitering?','standing around a station entrance for an hour','walking directly to a booked appointment','waiting at home for a delivery','standing around a station entrance for an hour','在公共入口无目的地久留可称 loiter。'),Q('loiter',3,1,'A sign saying “Do not loiter” asks people not to?','hang around','enter the building at all','speak to staff','hang around','loiter 的核心意思是逗留。'),Q('loiter',4,1,'Loiter often suggests lingering without?','a clear reason','a coat','a map','a clear reason','无明显目的常是 loiter 的语感。')]});
D('loll',{etymology:E('Loll is an old English verb of uncertain origin; it describes sitting or lying in a relaxed, loose, or lazy posture.','loll'),contexts:[C('loll.s1','午后休息','After finishing her chores, Jo lolled in the hammock with a book resting on her chest.','做完家务后，乔懒洋洋地躺在吊床上，胸口放着一本书。','After finishing her chores / Jo lolled in the hammock / with a book resting / on her chest.','loll 指懒洋洋地坐着或躺着，身体姿态放松。','她躺在吊床上休息，没有进行活动。')],mistakes:[M('He lolled upright at attention, perfectly rigid and ready to sprint at once.','He lolled in the chair with his shoulders loose and his feet stretched out.','僵直站立不符合懒散放松的姿态。')],quiz:[Q('loll',1,1,'To loll in a chair is to?','sit or recline lazily','stand at attention','run a race','sit or recline lazily','loll.s1 指懒洋洋地坐躺。'),Q('loll',2,1,'Which scene shows someone lolling?','a person sprawled comfortably on a sofa','a runner sprinting toward the finish','a guard standing rigidly','a person sprawled comfortably on a sofa','舒服地摊坐在沙发上体现 loll。'),Q('loll',3,1,'Loll suggests a posture that is?','relaxed and loose','formal and rigid','painfully upright','relaxed and loose','loll 带有懒散放松的姿态。'),Q('loll',4,1,'Which sentence is natural?','They lolled by the pool all afternoon.','They lolled the pool into a room.','The loll weighed two tons.','They lolled by the pool all afternoon.','人可以在泳池边懒散地休息。','grammar')]});
D('London',{etymology:E('London is the established English name of the United Kingdom’s capital; its ancient name is recorded in Latin as Londinium, while the earlier origin remains uncertain.','london'),contexts:[C('London.s1','城市地理','The train from Bristol arrived in London just before the evening rush began.','从布里斯托尔开来的火车在晚高峰开始前不久抵达伦敦。','The train from Bristol arrived / in London / just before / the evening rush began.','London.s1 指泰晤士河畔的英国首都。','列车从英国另一城市抵达首都。')],mistakes:[M('The itinerary listed London as a Scottish village on the North Sea rather than the UK capital on the Thames.','The itinerary listed London as the UK capital on the Thames.','London 是英国首都，位于泰晤士河畔，并非苏格兰村庄。')],quiz:[Q('London',1,1,'London is the capital of?','the United Kingdom','Australia','Canada','the United Kingdom','London.s1 是英国首都。'),Q('London',2,1,'Which river runs through London?','the Thames','the Nile','the Amazon','the Thames','伦敦位于泰晤士河畔。'),Q('London',3,2,'In a financial news headline, “London” may refer to?','the city’s financial center','a Scottish lake','a type of railway engine','the city’s financial center','London.s2 可转指伦敦金融城或英国政府。'),Q('London',4,1,'A traveler arriving in London has arrived in?','the UK capital','a sea turtle habitat only','a remote mountain pass','the UK capital','London 指英国首都。')]});
D('lone',{etymology:E('Lone is a shortened form of alone; it describes one person or thing by itself, with no others present.','lone'),contexts:[C('lone.s1','野外观察','A lone heron stood at the edge of the marsh while the rest of the flock remained in the trees.','其他鹭鸟仍在树上时，一只孤鹭独自站在沼泽边。','A lone heron stood / at the edge of the marsh / while the rest of the flock / remained in the trees.','lone.s1 表示单独的、没有同伴在旁的。','只有一只鹭鸟在沼泽边，其他鸟在别处。')],mistakes:[M('The lone guard worked with a large team of twenty colleagues standing beside him at all times.','The lone guard worked by himself at the remote gate.','身边一直有二十名同事，与 lone 的单独状态相反。')],quiz:[Q('lone',1,1,'A lone traveler is?','traveling alone','leading a large group','staying in a crowded dormitory','traveling alone','lone.s1 表示单独的。'),Q('lone',2,1,'Which phrase uses lone correctly?','a lone tree on the empty plain','a lone crowd of a thousand people','the lone of the house','a lone tree on the empty plain','平原上独自的一棵树可以称 a lone tree。','collocation'),Q('lone',3,1,'Lone is closest in meaning to?','solitary','crowded','collective','solitary','solitary 表示单独的。','meaning'),Q('lone',4,1,'A lone witness at the scene means?','one witness was there by themself','many witnesses arrived together','no witness was present','one witness was there by themself','lone 表示只有一个人。')]});
D('loneliness',{etymology:E('Loneliness is formed from lonely with -ness; it names the sadness of lacking companionship or feeling emotionally cut off.','loneliness'),contexts:[C('loneliness.s1','社区关怀','The weekly meal gave older residents a chance to talk and eased the loneliness of living alone.','每周聚餐让年长居民有机会交谈，也缓解了独居带来的寂寞。','The weekly meal gave older residents a chance to talk / and eased / the loneliness / of living alone.','loneliness 指缺少陪伴或感到与人隔绝而产生的悲伤。','定期交流为独居者带来陪伴。')],mistakes:[M('The program reduced loneliness by preventing residents from meeting, calling, or speaking to anyone.','The program reduced loneliness by creating regular chances for residents to meet and talk.','禁止交流会加重孤独感，而非缓解它。')],quiz:[Q('loneliness',1,1,'Loneliness is?','sadness from lacking companionship or connection','the physical distance between two cities','a long-lasting object','sadness from lacking companionship or connection','loneliness.s1 指寂寞感。'),Q('loneliness',2,1,'A person may feel loneliness even when?','others are nearby but they feel cut off','they are always surrounded by close friends','they are asleep alone for one minute','others are nearby but they feel cut off','孤独感也可能是情感上与人隔绝。'),Q('loneliness',3,1,'Which action may ease loneliness?','joining a welcoming weekly group','avoiding every conversation','moving farther from all friends','joining a welcoming weekly group','建立联系可能减轻寂寞。'),Q('loneliness',4,1,'Loneliness is the noun related to?','lonely','lobby','log','lonely','loneliness 由 lonely 加 -ness 构成。','word-formation')]});
D('lonely',{etymology:E('Lonely is formed from lone with -ly; it describes feeling unhappy because one is alone or describing an isolated place far from others.','lonely'),contexts:[C('lonely.s1','新城市生活','She felt lonely during her first weeks in the new city, before she had made any friends.','搬到新城市后的头几周，她还没有交到朋友，因此感到孤独。','She felt lonely / during her first weeks / in the new city / before she had made any friends.','lonely.s1 指因缺少朋友或陪伴而感到寂寞。','她尚未建立社交联系，感到不开心。'),C('lonely.s2','地理描写','A lonely farm stood several miles from the nearest village, surrounded by open fields.','一座偏僻的农场坐落在开阔田野中，距离最近的村庄有好几英里。','A lonely farm stood / several miles from the nearest village / surrounded / by open fields.','lonely.s2 描写偏僻、人迹稀少的地点。','农场远离村庄，周围空旷。')],mistakes:[M('The lonely farm stood in the center of a crowded city block with neighbors on every side.','The lonely farm stood far from the nearest village.','位于拥挤街区的农场并不偏僻。')],quiz:[Q('lonely',1,1,'A lonely person may feel?','sad because they lack companionship','proud of a large crowd','physically tall','sad because they lack companionship','lonely.s1 表示寂寞的情绪。'),Q('lonely',2,2,'A lonely road is likely?','isolated and far from other places','full of shops and crowds','a long-distance phone call','isolated and far from other places','lonely.s2 可形容偏僻道路。'),Q('lonely',3,1,'Which sentence describes a feeling?','I felt lonely after moving away from my friends.','The lonely cabin stood at the edge of the forest.','The loner repaired a roof.','I felt lonely after moving away from my friends.','主语体验情绪，句子使用情感义。'),Q('lonely',4,1,'Lonely and alone differ because lonely often emphasizes?','unhappiness about being alone','the number of rooms in a house','a person’s profession','unhappiness about being alone','lonely 常强调对独处感到难过。','confusable')]});
D('loner',{etymology:E('Loner is formed from lone with the person suffix -er; it describes someone who prefers solitude or does not readily join groups.','loner'),contexts:[C('loner.s1','人物刻画','The novel’s loner spent evenings restoring old radios and rarely attended neighborhood events.','小说中的独行者晚上常修复旧收音机，很少参加社区活动。','The novel’s loner spent evenings restoring old radios / and rarely attended / neighborhood events.','loner 指倾向独处、不容易参加群体活动的人。','人物独自进行爱好，很少加入社区活动。')],mistakes:[M('The reporter called the team captain a loner even though she organized every gathering and constantly sought company.','The reporter called the man who avoided group events and preferred solitude a loner.','积极组织活动、总爱与人相伴不符合 loner 的特点。')],quiz:[Q('loner',1,1,'A loner is someone who?','often prefers being alone','must live in a loft','works as a logger','often prefers being alone','loner.s1 指喜独处者。'),Q('loner',2,1,'Which person is most likely a loner?','someone who chooses solo hobbies and avoids most group events','someone who hosts a large gathering every night','someone who follows a crowd everywhere','someone who chooses solo hobbies and avoids most group events','主动偏好独处、少参加群体活动的人可称 loner。'),Q('loner',3,1,'Loner is formed from?','lone','long','logo','lone','loner 由 lone 加 -er 构成。','word-formation'),Q('loner',4,1,'A loner is a person, while loneliness is a?','feeling','railway engine','mineral','feeling','loner 是人，loneliness 是情绪或状态。','confusable')]});
D('lonesome',{etymology:E('Lonesome is formed from lone with -some; it means lonely or feeling sad because one is without companionship.','lonesome'),contexts:[C('lonesome.s1','远行途中','After weeks on the isolated route, the driver grew lonesome and called his family each night.','在偏僻路线上行驶数周后，司机渐渐感到孤单，每晚都给家人打电话。','After weeks on the isolated route / the driver grew lonesome / and called his family / each night.','lonesome 指因独处或缺少陪伴而感到孤独。','偏僻旅程使司机想念家人和陪伴。')],mistakes:[M('He felt lonesome because he was surrounded by close friends and was happy with their company all day.','He felt lonesome after spending several weeks without company.','持续陪伴且感到满足与 lonesome 的孤单情绪相反。')],quiz:[Q('lonesome',1,1,'If a traveler feels lonesome, the traveler feels?','sad from being alone','certain of a route','physically long','sad from being alone','lonesome.s1 表示孤独、寂寞。'),Q('lonesome',2,1,'Which situation may feel lonesome?','eating alone in a remote cabin for weeks','having dinner with close friends','attending a lively family reunion','eating alone in a remote cabin for weeks','长期独处可能令人孤单。'),Q('lonesome',3,1,'Lonesome is closest to?','lonely','logical','lofty','lonely','lonesome 和 lonely 意思相近。','meaning'),Q('lonesome',4,1,'Lonesome describes an emotional?','state','mineral deposit','railway part','state','lonesome 描述情绪状态。')]});
D('long',{etymology:E('Long is an old Germanic word; it describes great physical distance or duration, can modify time expressions, and as a verb means strongly desire something.','long'),contexts:[C('long.s1','道路测量','A long footbridge crosses the marsh and connects the two sections of the nature reserve.','一座很长的人行桥横跨沼泽，连接自然保护区的两个区域。','A long footbridge crosses the marsh / and connects / the two sections / of the nature reserve.','long.s1 描述空间距离大、长度较长。','桥横跨大片沼泽，长度显著。'),C('long.s4','探亲思念','After living abroad for years, she longed to hear her grandmother tell the old family stories.','在国外生活多年后，她渴望听祖母讲述那些家族往事。','After living abroad for years / she longed to hear her grandmother / tell / the old family stories.','long.s4 作动词，表示非常渴望某人或某事。','她强烈希望听到祖母讲故事。')],mistakes:[M('He longed for a reunion but felt no desire to see his family and hoped they would never visit.','He longed for a reunion because he strongly wanted to see his family again.','完全不想见家人，与 long for reunion 的渴望相矛盾。')],quiz:[Q('long',1,1,'A long bridge is?','great in physical length','shorter than a step','a person who rents a room','great in physical length','long.s1 表示空间上长。'),Q('long',2,2,'A long meeting lasts?','a great amount of time','only one second','a great physical distance','a great amount of time','long.s2 表示时间持续很久。'),Q('long',3,4,'To long for home is to?','strongly want to be home','measure the house','stay in a rented room','strongly want to be home','long.s4 表示渴望。'),Q('long',4,3,'Which sentence uses long as an adverb?','I have not seen her for long.','The long bridge is open.','They long for better weather.','I have not seen her for long.','long.s3 可作副词，表示长久地。','grammar')]});
D('long for',{etymology:E('Long for combines long in its older sense “desire greatly” with for; it means want something very much and wish to have it.','long for'),contexts:[C('long for.s1','家庭团聚','After months at sea, the sailors longed for a quiet evening at home.','在海上数月后，水手们渴望在家里度过一个安静的夜晚。','After months at sea / the sailors longed for / a quiet evening / at home.','long for 指非常渴望某物或某种经历，后接 for 加名词。','水手们盼望回家休息。')],mistakes:[M('She longed for a peaceful holiday but hoped she would be forced to work through every day.','She longed for a peaceful holiday because she strongly wanted time to rest.','希望假期每天被迫工作，与渴望休息相反。')],quiz:[Q('long for',1,1,'To long for a place is to?','want very much to be there','avoid thinking about it','measure its length','want very much to be there','long for.s1 指非常渴望。'),Q('long for',2,1,'Which construction is correct?','long for a chance to return','long at a chance return','long a chance for return','long for a chance to return','long for 后接渴望的对象。','collocation'),Q('long for',3,1,'If children long for their parent’s visit, they?','eagerly wish the parent would visit','hope the parent cancels the visit','do not know who the parent is','eagerly wish the parent would visit','long for 表示期待、渴望。'),Q('long for',4,1,'Long for is closest to?','yearn for','record','lock away','yearn for','yearn for 同样表示渴望。','meaning')]});
D('long life',{etymology:E('Long life combines long with life; it refers to living for many years or to a long period of continued existence.','long-life'),contexts:[C('long life.s1','健康研究','The study compared factors associated with a long life, including activity, diet, and access to care.','这项研究比较了与长寿相关的因素，包括运动、饮食和医疗可及性。','The study compared factors / associated with a long life / including activity, diet, / and access to care.','long life 指活很多年、寿命较长。','研究关注哪些因素与较长寿命有关。')],mistakes:[M('The report described a life lasting only a few days as a long life.','The report described the person who lived for nearly a century as having a long life.','只活几天与长寿含义相反。')],quiz:[Q('long life',1,1,'A person with a long life has?','lived for many years','traveled a great distance once','kept a detailed ship log','lived for many years','long life.s1 指长寿。'),Q('long life',2,1,'Which habit may support a long life?','regular preventive health care','avoiding every medical check','exposure to preventable hazards','regular preventive health care','健康管理可能有助于长寿。'),Q('long life',3,1,'Long life is about the length of someone’s?','existence','hair lock','rail journey','existence','此短语指寿命长短。'),Q('long life',4,1,'A lifespan of ninety-five years is an example of?','a long life','loitering','a long-distance route','a long life','九十五年寿命可称长寿。')]});
D('long-distance',{etymology:E('Long-distance combines long and distance; it describes travel or communication that covers a great distance.','long-distance'),contexts:[C('long-distance.s1','远程通信','The clinic arranged a long-distance consultation for a patient who lived on a distant island.','诊所为住在偏远岛屿的患者安排了远程问诊。','The clinic arranged a long-distance consultation / for a patient / who lived / on a distant island.','long-distance.s1 指跨越很长距离的旅行或通信。','患者住得远，因此安排远程会诊。')],mistakes:[M('They called the call long-distance even though the caller and recipient were in the same room.','They called the call long-distance because it connected people in different countries.','同处一室的通话不是远距离通信。')],quiz:[Q('long-distance',1,1,'A long-distance train travels?','a great distance','only across one room','without moving','a great distance','long-distance.s1 指远距离的。'),Q('long-distance',2,1,'A long-distance call connects people?','far apart','standing beside one another','who do not use phones','far apart','长途电话连接相距很远的人。'),Q('long-distance',3,1,'Which phrase is natural?','long-distance runner','long-distance teacup','long-distance short second','long-distance runner','long-distance 可修饰跑步者。','collocation'),Q('long-distance',4,1,'Long-distance describes distance, not necessarily?','duration','geography','travel','duration','它主要说距离，而非必然指持续时间。')]});
D('long-lasting',{etymology:E('Long-lasting combines long with the participial adjective lasting; it describes something that continues or remains effective for a long time.','long-lasting'),contexts:[C('long-lasting.s1','材料耐久性','The coating provides long-lasting protection against moisture, even in the humid storage room.','这种涂层能持久防潮，即使在潮湿的储藏室里也有效。','The coating provides / long-lasting protection / against moisture / even in the humid storage room.','long-lasting 指持续很长时间的、经久的。','防护效果在较长时间内保持有效。')],mistakes:[M('The battery was long-lasting because it lost all charge after ten minutes of ordinary use.','The battery was long-lasting because it powered the device for several days.','十分钟就耗尽与持久耐用的含义不符。')],quiz:[Q('long-lasting',1,1,'A long-lasting repair?','continues to work for a long time','fails immediately','covers a long road only','continues to work for a long time','long-lasting.s1 指持久的。'),Q('long-lasting',2,1,'Which might be long-lasting?','a durable protective coating','a one-use paper ticket','a candle that goes out in seconds','a durable protective coating','耐久涂层的效果会持续较长时间。'),Q('long-lasting',3,1,'Long-lasting is closest in meaning to?','durable','temporary','nearby','durable','durable 表示耐用持久。','meaning'),Q('long-lasting',4,1,'Long-lasting describes how long an effect?','continues','travels geographically','takes to measure','continues','long-lasting 强调效果持续时间。')]});
D('long-range',{etymology:E('Long-range combines long and range; it describes something able to cover a great distance or planning that looks far into the future.','long-range'),contexts:[C('long-range.s1','公共规划','The regional council approved a long-range plan for expanding rail service over the next twenty years.','地区委员会批准了一项未来二十年扩展铁路服务的长期规划。','The regional council approved / a long-range plan / for expanding rail service / over the next twenty years.','long-range.s1 可指覆盖远距离或着眼遥远未来的。','规划的时间跨度长达二十年。')],mistakes:[M('The committee called its proposal long-range even though it addressed only tomorrow’s schedule.','The committee presented a long-range proposal covering transport needs for the next two decades.','只规划明天安排不是着眼遥远未来的长期规划。')],quiz:[Q('long-range',1,1,'A long-range aircraft is designed to?','travel a great distance','stay inside one room','carry only local mail','travel a great distance','long-range.s1 可指远程的。'),Q('long-range',2,1,'A long-range plan considers?','the distant future','only the next five minutes','yesterday’s weather','the distant future','long-range.s1 也指长期的、着眼未来的。'),Q('long-range',3,1,'Which phrase is natural?','long-range forecast','long-range teaspoon','long-range short moment','long-range forecast','forecast 可以有较长期限。','collocation'),Q('long-range',4,1,'A long-range strategy differs from an immediate fix because it?','considers distant goals or effects','repairs nothing','must involve a physical rangefinder','considers distant goals or effects','长远策略考虑更远目标。')]});
D('long-standing',{etymology:E('Long-standing combines long and standing; it describes a condition, relationship, or problem that has existed for many years.','long-standing'),contexts:[C('long-standing.s1','社区关系','The two towns have a long-standing partnership that began with a shared flood-relief effort.','这两个城镇有着由来已久的合作关系，最初源于一次共同的洪灾救援行动。','The two towns have / a long-standing partnership / that began / with a shared flood-relief effort.','long-standing 指已经存在或持续多年的。','合作关系从过去延续至今。')],mistakes:[M('The long-standing agreement was signed this morning and had never existed before today.','The long-standing agreement had guided the two groups for several decades.','今天刚签且此前不存在的协议不能称由来已久。')],quiz:[Q('long-standing',1,1,'A long-standing custom has?','existed for many years','started five minutes ago','ended before it began','existed for many years','long-standing.s1 指由来已久的。'),Q('long-standing',2,1,'Which could be a long-standing dispute?','a conflict continuing for decades','an argument that began seconds ago','a question answered immediately','a conflict continuing for decades','持续数十年的冲突符合该词义。'),Q('long-standing',3,1,'Which phrase is natural?','a long-standing relationship','a long-standing second only','a long-standing fresh start yesterday','a long-standing relationship','关系可以持续多年。','collocation'),Q('long-standing',4,1,'Long-standing emphasizes that something?','has continued over time','covers a long physical distance only','is located near the speaker','has continued over time','它强调持续时间长。')]});
D('long-term',{etymology:E('Long-term combines long and term; it describes effects, plans, or commitments extending over a long period rather than a brief one.','long-term'),contexts:[C('long-term.s1','健康管理','The physician explained the long-term effects of the treatment and scheduled regular follow-up visits.','医生解释了这种治疗的长期影响，并安排了定期复诊。','The physician explained / the long-term effects / of the treatment / and scheduled regular follow-up visits.','long-term 指延续或考虑较长时间段的。','治疗效果需要在长期随访中观察。')],mistakes:[M('The report described a one-hour trial as a long-term study despite collecting no information after that hour.','The report described a five-year follow-up as a long-term study.','仅一小时的观察不属于长期研究。')],quiz:[Q('long-term',1,1,'A long-term plan covers?','a long period','one brief moment only','a large physical distance only','a long period','long-term.s1 指长期的。'),Q('long-term',2,1,'Which is a long-term consequence?','a health effect appearing over many years','a light switch turning on instantly','a short delay of two seconds','a health effect appearing over many years','多年后出现的影响属于长期后果。'),Q('long-term',3,1,'Which phrase is natural?','long-term investment','long-term one-second pause','long-term nearby village','long-term investment','投资常以长期视角讨论。','collocation'),Q('long-term',4,1,'Long-term is often contrasted with?','short-term','long-distance','long-lasting','short-term','long-term 与 short-term 相对。','confusable')]});
D('longevity',{etymology:E('Longevity comes through French from Latin longaevitas, from longus “long” and aevum “age”; it means long life or the ability to last.','longevity'),contexts:[C('longevity.s2','产品测试','The engineers tested the battery’s longevity by charging and discharging it hundreds of times.','工程师通过数百次充放电测试电池的使用寿命。','The engineers tested / the battery’s longevity / by charging and discharging it / hundreds of times.','longevity.s2 指物品能够持久使用、寿命长。','重复循环测试电池能否长期耐用。')],mistakes:[M('The battery showed great longevity because it stopped working after its first use.','The battery showed great longevity because it remained reliable through years of use.','首次使用后就失效说明寿命短。')],quiz:[Q('longevity',1,1,'Human longevity refers to?','living for many years','being physically tall','traveling a long distance','living for many years','longevity.s1 指长寿。'),Q('longevity',2,2,'A tool’s longevity is its ability to?','last for a long time','change its logo','move under its own power','last for a long time','longevity.s2 指物品的耐用寿命。'),Q('longevity',3,1,'Which factor might improve a machine’s longevity?','regular maintenance','constant overheating','never replacing worn parts','regular maintenance','维护可以延长机器的使用寿命。'),Q('longevity',4,1,'Longevity is related to the idea of?','long life or duration','lobbying officials','recording a ship log','long life or duration','longevity 含长寿、持久之意。','meaning')]});
D('longing',{etymology:E('Longing is the noun formed from long in the sense “desire greatly”; it means a strong wish for something one does not have.','longing'),contexts:[C('longing.s1','迁居思乡','Her longing for the coast grew stronger each winter she spent inland.','她每年冬天在内陆度过时，对海岸的向往都会更加强烈。','Her longing for the coast / grew stronger / each winter / she spent inland.','longing 指对尚未拥有或身处其中之物的强烈渴望。','她离开海岸后一直想念那里。')],mistakes:[M('His longing for a quiet home disappeared because he disliked the idea of peace and wanted noise at all times.','His longing for a quiet home reflected his strong wish to live somewhere peaceful.','排斥安静与渴望宁静的家相矛盾。')],quiz:[Q('longing',1,1,'A longing is?','a strong wish for something','a record of a voyage','a mineral vein','a strong wish for something','longing.s1 指强烈渴望。'),Q('longing',2,1,'Which phrase is natural?','a longing for home','a longing under the table','a longing weighs two miles','a longing for home','longing 常与 for 连用。','collocation'),Q('longing',3,1,'Someone with a longing to travel?','strongly wishes to travel','has already forgotten travel','cannot move at all','strongly wishes to travel','longing 指心中强烈的愿望。'),Q('longing',4,1,'Longing is related to which use of long?','to long for something','a long bridge','a long meeting','to long for something','longing 来自动词 long“渴望”。','word-formation')]});
D('longitude',{etymology:E('Longitude comes from Latin longitudo “length”; it measures position east or west of Greenwich and also names the north–south lines used to mark that position.','longitude'),contexts:[C('longitude.s1','地图阅读','The navigator checked the ship’s longitude to determine how far east it had sailed from Greenwich.','领航员查看船只的经度，以确定它从格林尼治向东航行了多远。','The navigator checked / the ship’s longitude / to determine / how far east it had sailed from Greenwich.','longitude.s1 指以格林尼治为基准，表示地球东西位置的经度。','经度反映相对于格林尼治向东或向西的位置。')],mistakes:[M('The map gave the island’s longitude as its distance north of the equator.','The map gave the island’s latitude north of the equator and its longitude east of Greenwich.','南北位置是 latitude；longitude 表示东西位置。')],quiz:[Q('longitude',1,1,'Longitude measures position east or west of?','Greenwich','the equator only','the North Pole only','Greenwich','longitude.s1 以格林尼治为基准测量东西位置。'),Q('longitude',2,2,'A line of longitude runs from?','the North Pole to the South Pole','east to west around the equator only','one town to another along a road','the North Pole to the South Pole','longitude.s2 经线连接南北两极。'),Q('longitude',3,1,'Which coordinate tells how far east a place is from Greenwich?','longitude','latitude','altitude','longitude','经度表示相对于格林尼治的东西位置。'),Q('longitude',4,1,'Longitude and latitude are both used to identify?','locations on Earth','a person’s age','the length of a sentence','locations on Earth','经纬度共同用于确定地球上的地点。')]});
D('longitudinal',{etymology:E('Longitudinal is formed from longitude with -al; it describes direction along the length of an object or a study that follows the same subjects over time.','longitudinal'),contexts:[C('longitudinal.s1','研究设计','The longitudinal study followed the same families for twelve years to track changes in sleep habits.','这项纵向研究对同一批家庭进行了十二年跟踪，以记录睡眠习惯的变化。','The longitudinal study followed the same families / for twelve years / to track changes / in sleep habits.','longitudinal.s1 可指沿长度方向的，也可指随时间跟踪同一对象的研究。','研究长期观察同一批家庭的变化。')],mistakes:[M('The researchers called their one-time survey longitudinal even though they never returned to or followed the participants.','The researchers called the twelve-year follow-up of the same families a longitudinal study.','一次性调查没有跨时间跟踪，不能体现纵向研究。')],quiz:[Q('longitudinal',1,1,'A longitudinal study follows?','the same subjects over time','different subjects once at one moment only','only the length of a word','the same subjects over time','longitudinal.s1 可指跨时间跟踪研究。'),Q('longitudinal',2,1,'A longitudinal crack runs?','along the length of an object','across its width only','around its outer edge only','along the length of an object','longitudinal 也指沿长轴方向。'),Q('longitudinal',3,1,'Which project is longitudinal?','measuring the same children each year for a decade','surveying a new group once this morning','counting the pages in one report','measuring the same children each year for a decade','多年重复观察同一批儿童是纵向研究。'),Q('longitudinal',4,1,'Longitudinal contrasts with a study that is?','a one-time snapshot','tracked over many years','measured along a length','a one-time snapshot','一次性横截面调查与纵向跟踪相对。','confusable')]});
D('longtime',{etymology:E('Longtime combines long and time; as an adjective it describes a relationship, condition, or association that has lasted for a long while.','longtime'),contexts:[C('longtime.s1','长期合作','A longtime collaborator reviewed the manuscript before it went to the publisher.','一位长期合作者在手稿交给出版商之前进行了审阅。','A longtime collaborator / reviewed the manuscript / before it went / to the publisher.','longtime 形容持续已久的关系或状态。','两人长期合作，因此称为 longtime collaborators。')],mistakes:[M('She was a longtime employee despite having started the job this morning and never working there before.','She was a longtime employee after working for the company for twenty years.','刚入职与为时已久的雇佣关系相反。')],quiz:[Q('longtime',1,1,'A longtime friend is someone who?','has been a friend for many years','met you a minute ago','lives a long distance away necessarily','has been a friend for many years','longtime.s1 指关系持续很久。'),Q('longtime',2,1,'Which phrase is natural?','a longtime member of the club','a longtime second ago','a longtime close to the door','a longtime member of the club','longtime 可修饰长期成员。','collocation'),Q('longtime',3,1,'A longtime condition has?','lasted for a long while','just begun moments ago','already disappeared','lasted for a long while','longtime 描述持续已久的状态。'),Q('longtime',4,1,'Longtime is generally written as?','one word','two unrelated verbs','a hyphenated verb only','one word','longtime 作形容词通常写作一个词。','spelling')]});
D('loo',{etymology:E('Loo is an informal British word for a toilet; its deeper origin is uncertain, so the history is left open.','loo'),contexts:[C('loo.s1','日常问路','At the station, she asked a member of staff where the loo was before boarding her train.','在车站，她上火车前向工作人员询问厕所在哪里。','At the station / she asked a member of staff / where the loo was / before boarding her train.','loo 是英式口语中“厕所”的说法。','乘客在车站询问可使用的卫生间。')],mistakes:[M('The visitor asked where the loo was because she wanted to find the railway engine, not a toilet.','The visitor asked where the loo was because she needed to find a toilet.','英式口语 loo 指厕所，不是机车。')],quiz:[Q('loo',1,1,'In informal British English, a loo is a?','toilet','railway engine','long-distance train','toilet','loo.s1 指厕所。'),Q('loo',2,1,'Someone asking “Where’s the loo?” wants to find?','a restroom','a ticket office','a map of longitude','a restroom','该表达是在询问厕所位置。'),Q('loo',3,1,'Loo is informal and especially common in?','British English','formal legal writing only','ancient mathematics','British English','loo 常见于英式口语。','register'),Q('loo',4,1,'Which meaning fits “The loo is down the hall”?','the toilet is down the hall','the train engine is down the hall','the hall is very long','the toilet is down the hall','句子中的 loo 指走廊尽头的厕所。')]});
D('look',{etymology:E('Look is an old Germanic verb and noun; it can mean direct one’s eyes, seem, search, appearance, or an act of viewing.','look'),contexts:[C('look.s3','失物查找','We looked for the missing key beneath the bench before calling the caretaker.','我们在给管理员打电话之前，先在长椅下面寻找丢失的钥匙。','We looked for the missing key / beneath the bench / before calling / the caretaker.','look.s3 指试图找到某人或某物，常与 for 连用。','他们主动查找遗失的钥匙。')],mistakes:[M('She looked for her glasses by refusing to search anywhere and deciding they could not be missing.','She looked for her glasses under the papers and beside the lamp.','拒绝寻找就不属于 look for。')],quiz:[Q('look',1,1,'To look at a painting is to?','turn your eyes toward it','try to rent a room','write down a voyage','turn your eyes toward it','look.s1 指把目光转向某物。'),Q('look',2,2,'“You look tired” means you?','seem tired','are searching for tiredness','have a particular clothing style only','seem tired','look.s2 表示看起来、似乎。'),Q('look',3,3,'To look for a key is to?','try to find it','turn it into a loop','watch it without searching','try to find it','look.s3 指寻找。'),Q('look',4,4,'A person’s look can refer to their?','appearance','longitude','lodging arrangement','appearance','look.s4 可指外表或式样。')]});
D('look after',{etymology:E('Look after is a phrasal verb combining look with after; it means take care of a person, animal, or thing.','look-after'),contexts:[C('look after.s1','家庭照护','While her neighbors were away, Mina looked after their cat and watered the balcony plants.','邻居外出时，米娜照看他们的猫，并给阳台植物浇水。','While her neighbors were away / Mina looked after their cat / and watered / the balcony plants.','look after 指负责照料、看护某人或某物。','她承担喂猫和照料植物的责任。')],mistakes:[M('He looked after the child by leaving the child alone without food, supervision, or any way to contact him.','He looked after the child by preparing meals and staying nearby until the parents returned.','放任无人照料与 look after 的照顾义相反。')],quiz:[Q('look after',1,1,'To look after a child is to?','take care of the child','search for the child only','watch the child from a distance without helping','take care of the child','look after.s1 指照料。'),Q('look after',2,1,'Which sentence uses look after correctly?','Can you look after my dog this weekend?','Can you look after for my dog this weekend?','Can you look my dog after the weekend?','Can you look after my dog this weekend?','look after 后直接接照料对象。','collocation'),Q('look after',3,1,'Someone looking after a garden might?','water its plants','leave every plant to dry','sell the house next door','water its plants','照料花园包括给植物浇水。'),Q('look after',4,1,'Look after is closest to?','care for','look at','look like','care for','care for 与 look after 都可表示照料。','meaning')]});
D('look around',{etymology:E('Look around combines look with the directional particle around; it means inspect a place by looking in different directions.','look-around'),contexts:[C('look around.s1','房屋参观','The couple looked around the empty apartment before deciding whether it had enough storage.','这对夫妇在决定储物空间是否充足之前，先四处查看了空公寓。','The couple looked around / the empty apartment / before deciding / whether it had enough storage.','look around 指环顾四周或在某处四下查看。','他们查看房间不同区域以了解空间情况。')],mistakes:[M('The visitors looked around the gallery by keeping their eyes shut and refusing to inspect any room.','The visitors looked around the gallery and examined its rooms and exhibits.','闭眼不看就没有进行环顾查看。')],quiz:[Q('look around',1,1,'To look around a room is to?','look in different directions and inspect it','leave without entering','search only one pocket','look in different directions and inspect it','look around.s1 指四处看看。'),Q('look around',2,1,'Which sentence uses the phrase naturally?','We looked around the market before choosing a stall.','We looked around for the answer in a dictionary.','We looked around our friend because she needed care.','We looked around the market before choosing a stall.','在市场四处查看可用 look around。'),Q('look around',3,1,'A visitor may look around a museum to?','see its rooms and displays','care for a neighbor’s pet','find a word’s definition only','see its rooms and displays','参观时环顾展厅。'),Q('look around',4,1,'Look around focuses on?','examining a place from different directions','taking care of a person','resembling another object','examining a place from different directions','该短语指环顾某地。')]});
D('look for',{etymology:E('Look for combines look with for; it means search or try to find a person or thing.','look-for'),contexts:[C('look for.s1','旅行准备','Before leaving the campsite, we looked for the map that had fallen behind the stove.','离开营地之前，我们寻找掉在炉子后面的地图。','Before leaving the campsite / we looked for the map / that had fallen / behind the stove.','look for 指试图找到某人或某物。','他们主动搜寻遗失的地图。')],mistakes:[M('She looked for her passport by deciding not to search and boarding without checking her bag.','She looked for her passport through the pockets of her travel bag.','不进行搜寻不符合 look for 的含义。')],quiz:[Q('look for',1,1,'To look for a document is to?','try to find it','take care of it','appear similar to it','try to find it','look for.s1 指寻找。'),Q('look for',2,1,'Which phrase is correctly formed?','look for a missing glove','look after a missing glove to find it','look into a missing glove at the station','look for a missing glove','寻找对象时使用 look for。','collocation'),Q('look for',3,1,'A mechanic might look for?','the source of an engine noise','a quiet person to care for','a view from a window','the source of an engine noise','技工会查找噪音来源。'),Q('look for',4,1,'Look for is closest to?','search for','resemble','care for','search for','search for 与 look for 意义接近。','meaning')]});
D('look into',{etymology:E('Look into combines look with into; it means investigate a question, problem, or situation to learn more about it.','look-into'),contexts:[C('look into.s1','事故调查','The safety board will look into the equipment failure before deciding whether the machine can return to service.','安全委员会将在决定机器能否恢复使用之前调查设备故障。','The safety board will look into the equipment failure / before deciding / whether the machine / can return to service.','look into 指调查、研究某个问题以了解详情。','委员会要先查明故障原因。')],mistakes:[M('The board looked into the failure by refusing to examine the machine, the records, or the witnesses.','The board looked into the failure by examining the machine and interviewing its operators.','拒绝调查相关证据与 look into 的含义相反。')],quiz:[Q('look into',1,1,'To look into a complaint is to?','investigate it','care for the person who made it only','make it look attractive','investigate it','look into.s1 指调查。'),Q('look into',2,1,'Which sentence uses look into correctly?','The agency is looking into reports of contaminated water.','The agency is looking into the baby every night as a sitter.','The agency looks into like its neighbor.','The agency is looking into reports of contaminated water.','调查报告可以用 look into 表达。','collocation'),Q('look into',3,1,'A manager might look into why?','a delivery arrived late','a window faces the garden','a pet needs daily care','a delivery arrived late','调查迟到原因符合 look into。'),Q('look into',4,1,'Look into means examine a matter in order to?','find out more','make it disappear immediately','compare its appearance','find out more','调查的目的在于弄清更多信息。')]});
D('look like',{etymology:E('Look like combines look with like; it means have an appearance similar to a person or thing, and can also introduce an apparent situation.','look-like'),contexts:[C('look like.s1','外貌比较','In the old photograph, her son looks like his grandfather, especially around the eyes.','在那张旧照片里，她的儿子看起来很像祖父，尤其是眼睛周围。','In the old photograph / her son looks like his grandfather / especially / around the eyes.','look like 指外表与某人或某物相似。','相似点体现在眼睛和整体外貌。')],mistakes:[M('The child looks like his father even though their faces, features, and appearance are entirely different.','The child looks like his father because they share the same eyes and smile.','外貌完全不同就不能说明 looks like。')],quiz:[Q('look like',1,1,'If a child looks like a parent, the child?','has a similar appearance','is taking care of the parent','is searching for the parent','has a similar appearance','look like.s1 指看起来相像。'),Q('look like',2,1,'Which construction is correct?','That cloud looks like a ship.','That cloud looks like to a ship.','That cloud looks for a ship.','That cloud looks like a ship.','look like 后可直接接相似对象。','grammar'),Q('look like',3,1,'If the sky looks like rain, it?','appears that rain may come','is investigating rain','is caring for rain','appears that rain may come','该结构也可表示看来可能发生某事。'),Q('look like',4,1,'Look like is used to describe?','resemblance or an apparent situation','a formal investigation only','an act of caring for someone','resemblance or an apparent situation','look like 可表示相似或似乎。')]});
D('look onto',{etymology:E('Look onto combines look with onto; it describes a window, room, or building that faces or has a view over a place.','look-onto'),contexts:[C('look onto.s1','住宅视野','The kitchen windows look onto a small courtyard shaded by an old pear tree.','厨房的窗户面向一个小庭院，庭院里有一棵老梨树遮阴。','The kitchen windows look onto / a small courtyard / shaded / by an old pear tree.','look onto 指窗户或建筑面向、俯瞰某个地方。','窗户朝向庭院，可以看到院内景象。')],mistakes:[M('The bedroom looked onto the courtyard even though its only window faced a solid wall and offered no view outside.','The bedroom looked onto the courtyard through its wide window.','没有朝向庭院的窗户就看不到该景观。')],quiz:[Q('look onto',1,1,'A window that looks onto a garden?','faces the garden and gives a view of it','searches for the garden','takes care of the garden','faces the garden and gives a view of it','look onto.s1 指面向或俯瞰地点。'),Q('look onto',2,1,'Which sentence uses look onto correctly?','The balcony looks onto the river.','The balcony looks onto for the river.','The balcony looks after the river.','The balcony looks onto the river.','建筑视野可用 look onto 表达。','collocation'),Q('look onto',3,1,'A room may look onto?','a courtyard outside its windows','a report it is investigating','a person it resembles only','a courtyard outside its windows','房间可以面向窗外庭院。'),Q('look onto',4,1,'Look onto describes a view or?','orientation toward a place','care of a person','a search for lost keys','orientation toward a place','该短语指朝向某地点。')]});
D('look up',{etymology:E('Look up combines look with up; in this phrasal verb it means search for information in a reference source.','look-up'),contexts:[C('look up.s1','词典使用','When she encountered an unfamiliar term, she looked it up in a medical dictionary.','遇到不熟悉的术语时，她在医学词典里查了它。','When she encountered an unfamiliar term / she looked it up / in a medical dictionary.','look up 指在书籍或网络资料中查找信息。','她通过查阅词典获得词义。')],mistakes:[M('He looked up the word by closing every reference source and refusing to search for its meaning.','He looked up the word in a dictionary and noted its definition.','拒绝查找不能称为 look up。')],quiz:[Q('look up',1,1,'To look up a word is to?','search for its information in a reference source','take care of the word','make the word resemble another','search for its information in a reference source','look up.s1 指查阅词语信息。'),Q('look up',2,1,'Which sentence uses look up correctly?','I looked up the train time online.','I looked up after my neighbor’s dog.','I looked up a person to resemble my face.','I looked up the train time online.','在网上查时刻表可用 look up。'),Q('look up',3,1,'A dictionary is useful when you need to look up?','a word’s meaning','a room’s view','a pet’s daily needs','a word’s meaning','词典可查词义。'),Q('look up',4,1,'Look up often takes which object?','information or a word','a person receiving care','a place a window faces','information or a word','look up 常接待查信息。','collocation')]});
D('lookout',{etymology:E('Lookout combines look and out; it can mean a place or person positioned to watch for danger or developments.','lookout'),contexts:[C('lookout.s1','海岸安全','The lookout warned the crew when dark clouds began to gather beyond the headland.','海岬外乌云开始聚集时，瞭望员向船员发出了警告。','The lookout warned the crew / when dark clouds began to gather / beyond the headland.','lookout 可指负责观察危险的人，也可指观察用的瞭望处。','瞭望员观察天气并向船员预警。')],mistakes:[M('The lookout gave no warning because he was appointed to guard the coast but refused to watch the horizon.','The lookout watched the horizon and warned the crew about the approaching storm.','不观察周围就不能履行 lookout 的警戒职责。')],quiz:[Q('lookout',1,1,'A lookout is someone who?','watches for danger','repairs a railway engine','rents a room','watches for danger','lookout.s1 可指瞭望警戒的人。'),Q('lookout',2,1,'A mountain lookout may be?','a place with a view used for watching','a room below a roof','a deposit of ore','a place with a view used for watching','lookout 也指瞭望地点。'),Q('lookout',3,1,'Which phrase is natural?','keep a lookout for smoke','keep a lookout for a place to lodge after care','keep looking after the view for danger','keep a lookout for smoke','keep a lookout for 意为留意、警戒。','collocation'),Q('lookout',4,1,'A lookout on a ship might scan?','the horizon for hazards','a dictionary for definitions','a tree trunk for timber','the horizon for hazards','船上瞭望员监视海平线和危险。')]});
D('loom',{etymology:E('Loom has uncertain origins as a verb meaning appear indistinctly or threateningly; as a noun it names a frame or machine used for weaving cloth.','loom'),contexts:[C('loom.s2','项目风险','With the deadline only two days away, the possibility of losing the grant loomed over the research team.','截止日期只剩两天，失去资助的可能性笼罩着研究团队。','With the deadline only two days away / the possibility of losing the grant / loomed over / the research team.','loom.s2 指令人担忧的事情即将发生、迫在眉睫。','期限临近使失去资助的风险变得紧迫。')],mistakes:[M('The funding deadline loomed over the team even though it was years away and posed no immediate concern.','The funding deadline loomed over the team because it was only days away.','遥远且不构成近期威胁的事并不迫在眉睫。')],quiz:[Q('loom',1,1,'A mountain that looms through fog?','appears as a large unclear shape','is woven into cloth','is searched for in a dictionary','appears as a large unclear shape','loom.s1 描述形状隐约显现。'),Q('loom',2,2,'A looming deadline is?','about to arrive and often worrying','already canceled and forgotten','very far away with no urgency','about to arrive and often worrying','loom.s2 表示令人担忧地临近。'),Q('loom',3,3,'A loom is a machine used for?','weaving cloth','measuring longitude','locking a door','weaving cloth','loom.s3 指织布机。'),Q('loom',4,1,'Which sentence uses loom for an approaching problem?','A shortage of fuel loomed as winter began.','The carpenter repaired the loom for weaving.','The hill loomed faintly in the mist.','A shortage of fuel loomed as winter began.','短缺在冬季开始时迫近，属于 looming problem。')]});
D('looming',{etymology:E('Looming is the present participle and adjective from loom; it describes something that seems likely to happen very soon, often with a threatening or worrying effect.','looming'),contexts:[C('looming.s1','学业安排','Students faced a looming examination and used the weekend to review the hardest chapters.','学生们面临一场迫近的考试，于是利用周末复习最难的章节。','Students faced / a looming examination / and used the weekend / to review the hardest chapters.','looming.s1 指即将发生、常带有压力或忧虑的事情。','考试很快就要来临，学生需要准备。')],mistakes:[M('The looming examination was scheduled for next year and caused no immediate pressure at all.','The looming examination was scheduled for Monday, only a few days away.','明年才举行的考试并非即将迫近。')],quiz:[Q('looming',1,1,'A looming event is?','likely to happen very soon','certain never to happen','already finished long ago','likely to happen very soon','looming.s1 指即将发生。'),Q('looming',2,1,'Which is a looming problem?','a storm forecast to arrive tonight','a storm that passed last year','a storm in a fictional tale only','a storm forecast to arrive tonight','今晚将到的风暴是迫近问题。'),Q('looming',3,1,'Looming often carries a sense of?','concern or threat','celebration only','physical smallness','concern or threat','looming 常带担忧或威胁感。'),Q('looming',4,1,'Looming is related to the verb?','loom','look','lodge','loom','looming 是 loom 的分词形容词。','word-formation')]});
D('loop',{etymology:E('Loop comes through Dutch from a word for a running or curved form; it can name a ring-like shape, a repeating circuit or process, and the act of forming or moving in a curve.','loop'),contexts:[C('loop.s2','程序设计','The audio clip played in a loop until the technician switched the test off.','这段音频循环播放，直到技术人员关闭测试。','The audio clip played / in a loop / until the technician / switched the test off.','loop.s2 指反复运行的过程、回路或录音片段。','音频从头到尾不断重复播放。')],mistakes:[M('The clip played in a loop once and then stopped forever, without repeating.','The clip played in a loop, restarting automatically after each playback.','只播放一次并停止不是循环播放。')],quiz:[Q('loop',1,1,'A loop of rope is?','a ring-like curved shape','a long-distance plan','a small hotel room','a ring-like curved shape','loop.s1 指环状物。'),Q('loop',2,2,'A video on a loop?','repeats continuously','plays once only','is stored in a loft','repeats continuously','loop.s2 指重复循环。'),Q('loop',3,3,'To loop a cable around a post is to?','form a curve or ring around it','look for it online','cut it into a log','form a curve or ring around it','loop.s3 作动词指使成圈或环绕。'),Q('loop',4,1,'Which is a loop in a computer program?','a sequence that repeats','a one-time message','a mineral vein','a sequence that repeats','程序中的循环会重复执行。')]});
D('loophole',{etymology:E('Loophole originally meant a narrow opening in a wall, especially one for observing or shooting; figuratively it is a weakness in a rule that can be exploited.','loophole'),contexts:[C('loophole.s1','法规解读','The company used a loophole in the reporting rule to delay disclosure without technically breaking the law.','公司利用报告规则中的漏洞，在技术上不违法的情况下推迟了披露。','The company used / a loophole in the reporting rule / to delay disclosure / without technically breaking the law.','loophole.s1 指规则中的薄弱处，可能被利用来规避要求。','公司利用规定未覆盖的情形规避披露时间要求。')],mistakes:[M('The lawyer found a loophole in the law even though the text had no gap, ambiguity, or exploitable exception.','The lawyer found a loophole in the law that allowed the client to avoid the requirement.','无可利用的规则薄弱处就没有 loophole。')],quiz:[Q('loophole',1,1,'A loophole in a rule is?','a weakness that can be exploited','a perfect enforcement mechanism','a long-standing friendship','a weakness that can be exploited','loophole.s1 指规则漏洞。'),Q('loophole',2,2,'A loophole in an old wall was?','a narrow opening','a large room below a roof','a machine for weaving','a narrow opening','loophole.s2 指墙上的窄孔。'),Q('loophole',3,1,'Someone uses a legal loophole to?','avoid a requirement through a gap in the rule','follow every rule exactly as intended','repair a hole in a roof','avoid a requirement through a gap in the rule','利用规则漏洞可规避要求。'),Q('loophole',4,1,'Which phrase is natural?','close a loophole in the regulation','lodge a loophole for a week','look after a loophole as a person','close a loophole in the regulation','修补规则漏洞可说 close a loophole。','collocation')]});
D('loose',{etymology:E('Loose comes from Old Norse lauss, “free or unfastened”; it describes something not firmly fixed or not fitting tightly.','loose'),contexts:[C('loose.s1','家庭维修','The screw had worked loose, so the cabinet door sagged whenever someone opened it.','螺丝已经松动，因此每次有人打开柜门时，门板都会下垂。','The screw had worked loose / so the cabinet door sagged / whenever someone opened it.','loose.s1 指没有固定牢、松动或不紧的。','松动的螺丝无法稳固支撑柜门。')],mistakes:[M('The screw was loose and firmly tightened in place, so it could not move at all.','The screw was loose and shifted when the cabinet door moved.','完全紧固无法移动，与 loose 的松动义矛盾。')],quiz:[Q('loose',1,1,'A loose button is?','not firmly attached','perfectly secured','a long-distance signal','not firmly attached','loose.s1 指未固定牢。'),Q('loose',2,1,'Which sentence uses loose correctly?','One tooth was loose and moved when she touched it.','One tooth was loose because it was permanently fused in place.','The loose was over the river.','One tooth was loose and moved when she touched it.','松动的牙齿可以活动。'),Q('loose',3,1,'A loose lid may?','come off easily','be impossible to open because it is welded shut','refer to a person’s long life','come off easily','盖子松动时容易脱落。'),Q('loose',4,1,'Loose is the opposite of?','tight','long','local','tight','tight 表示紧，与 loose 相反。','confusable')]});
D('loosely',{etymology:E('Loosely is the adverb from loose; it means in a way that is not tightly fastened, or approximately rather than exactly.','loosely'),contexts:[C('loosely.s2','概念比较','The journalist used “digital neighbor” loosely to describe people who interact online but have never met.','记者宽泛地使用“数字邻居”一词，指那些在线互动但从未见过面的人。','The journalist used “digital neighbor” loosely / to describe people / who interact online / but have never met.','loosely.s2 表示大致、宽泛或不十分精确地。','记者采用宽泛用法，而非正式严格定义。')],mistakes:[M('The report used the term loosely but insisted it was a precise technical label with no broader or approximate meaning.','The report used the term loosely to cover several related but not identical cases.','若严格精确限定，就不是宽泛使用术语。')],quiz:[Q('loosely',1,1,'A loosely tied scarf is?','not tied tightly','fastened with a permanent knot','made of metal','not tied tightly','loosely.s1 指松散地系着。'),Q('loosely',2,2,'To use a term loosely is to use it?','approximately or broadly','with a strict technical definition only','without saying it aloud','approximately or broadly','loosely.s2 指宽泛、不精确地使用。'),Q('loosely',3,1,'Which sentence uses loosely to mean “not tightly”?','She loosely wrapped the scarf around her neck.','She loosely defined the category in a broad way.','The loosely was under the bed.','She loosely wrapped the scarf around her neck.','loosely 修饰 wrapping，说明没有紧紧包裹。'),Q('loosely',4,1,'Which sentence uses loosely to mean “approximately”?','The label is used loosely for several related designs.','The cable hung loosely from its clip.','She tied the ribbon loosely.','The label is used loosely for several related designs.','对类别标签的宽泛使用是 approximate sense。')]});

})();
